/* GENERÁLT FÁJL – tests/../build_exams.py hozza létre a hivatalos PDF-ekből. Ne szerkeszd kézzel. */
(function (root) {
  const PO = (root.PO = root.PO || {});
  PO.exams = [{"id": "2026okt", "cim": "2026. október", "datum": "2026. október 22.", "ido": 240, "kod": null, "forras": "Oktatási Hivatal – emelt szintű fizika írásbeli feladatlap és javítási-értékelési útmutató", "I": [{"nr": 1, "kepek": [{"src": "assets/exams/2026okt/I-01.png", "w": 1058, "h": 254}], "szoveg": "1. Egy könnyű, nagy méretű strandlabdát függőlegesen magasra dobunk, majd a visszaeső labdát elkapjuk. Mi tart hosszabb ideig, a labda emelkedése vagy a visszaesése? A) Az emelkedése tart hosszabb ideig. B) A visszaesése tart hosszabb ideig. C) Egyforma ideig tart az emelkedés és a visszaesés. D) A válasz a kezdősebességtől függ.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 2, "kepek": [{"src": "assets/exams/2026okt/I-02.png", "w": 1058, "h": 277}], "szoveg": "2. Egy áramkörbe 1,5 Ω nagyságú ellenállást kellene beillesztenünk, de csak egyforma, 1 Ω nagyságú ellenállásaink vannak. Legalább hány 1 Ω -os ellenállást kell felhasználnunk, hogy a feladatot teljesítsük? A) Legalább kettőt. B) Legalább hármat. C) Legalább négyet. D) Nem lehet megoldani a feladatot, ugyanis ha 1 Ω-os ellenállásokat kötünk össze, csak egész szám lehet az eredő ellenállás értéke.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 3, "kepek": [{"src": "assets/exams/2026okt/I-03.png", "w": 1058, "h": 195}], "szoveg": "3. Melyik anyagdarab tartalmaz több neutront? 1 kg 235 U izotóp, vagy pedig 1 kg 12 C izotóp? A) Az urán. B) A szén. C) Egyforma számú neutront tartalmaz a két anyagdarab.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 4, "kepek": [{"src": "assets/exams/2026okt/I-04.png", "w": 1058, "h": 292}], "szoveg": "4. Egy hintán ülő gyerek v sebességgel halad át a hinta középső (függőleges) helyzetén, majd mozgása lelassul, és egy pillanatra megáll a hintamozgás felső holtpontján. A hintakötél ekkor kb. 45 fokos szöget zár be a függőlegessel. A mozgás során rá ható erők közül melyik fékezte le a mozgását, amíg a függőleges helyzetből a felső holtpontra ért? A) A kötélerő. B) A gravitációs erő. C) Mindkét erő hozzájárult a hinta sebességének csökkenéséhez.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 5, "kepek": [{"src": "assets/exams/2026okt/I-05.png", "w": 1058, "h": 395}], "szoveg": "5. Egy dugattyús hengerbe zárt ideális gázzal a mellékelt p – V diagramon feltüntetett három, az A pontból a C pontba vezető állapotváltozást hajtunk végre. Melyik folyamatban kellett a legtöbb hőt közölni a gázzal? A) Az 1. folyamatban. B) A 2. folyamatban. C) A 3. folyamatban. D) Egyik folyamatban sem kellett hőt közölni a gázzal, hiszen a kezdő- és a végállapot hőmérséklete megegyezik.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 6, "kepek": [{"src": "assets/exams/2026okt/I-06.png", "w": 1058, "h": 254}], "szoveg": "6. Az artériák (ütőerek) belső falán képződő kemény vagy lágy lerakódást plakknak hívják. Ahol plakk keletkezik, ott lecsökken az ér keresztmetszete. Hogyan változik meg a véráramlás sebessége és a vérnyomás a plakkok által okozott szűkületben? A) A véráramlás sebessége is, a vér nyomása is megnő. B) A véráramlás sebessége is, a vér nyomása is lecsökken. C) A véráramlás sebessége lecsökken, a vér nyomása megnő. D) A véráramlás sebessége megnő, a vér nyomása lecsökken.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 7, "kepek": [{"src": "assets/exams/2026okt/I-07.png", "w": 1058, "h": 293}], "szoveg": "7. Függőleges, nyújtatlan rugó felső végét rögzítjük, alsó végére m tömegű testet akasztunk úgy, hogy a testet közben fogjuk, így a rugó nyújtatlan állapotban marad. Ezután a testet lökésmentesen elengedjük. Mekkora a test gyorsulása az elengedést követően mozgásának legfelső, középső, illetve legalsó pontjában? A) a = g; a = 0; a = g felső közép alsó B) a = g; a = 0; a = -g felső közép alsó C) a = 0; a = g; a = 2g felső közép alsó D) a = 0; a = g; a = 0 felső közép alsó", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 8, "kepek": [{"src": "assets/exams/2026okt/I-08.png", "w": 1058, "h": 546}], "szoveg": "8. Egy atom színképének 6 vonalát mutatja az ábra a frekvencia függvényében. Az alábbiak közül melyik rajz szemléltetheti az atom elektronpályáinak energiaszintjeit? A) Az A) ábra. B) A B) ábra. C) A C) ábra.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 9, "kepek": [{"src": "assets/exams/2026okt/I-09.png", "w": 1058, "h": 254}], "szoveg": "9. Két töltött részecske közül az egyik harmonikus rezgőmozgást végez, a másik egyenletes körmozgást. Melyik részecske bocsát ki elektromágneses hullámokat a mozgása során? A) Csak az, amelyik rezgőmozgást végez. B) Csak az, amelyik körmozgást végez. C) Mindkét részecske kibocsát elektromágneses hullámokat. D) Egyik részecske sem bocsát ki elektromágneses hullámokat.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 10, "kepek": [{"src": "assets/exams/2026okt/I-10.png", "w": 1058, "h": 264}], "szoveg": "10. Két követ vízszintesen hajítunk el. Az első követ 5 m magasról, 10 m/s sebességgel, a másodikat pedig 10 m magasról, 5 m/s sebességgel. Melyik kő repül messzebb a vízszintes talajon mérve? A) Az első. B) A második. C) Egyforma messze repülnek. D) Nem lehet eldönteni a megadott információk alapján.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 11, "kepek": [{"src": "assets/exams/2026okt/I-11.png", "w": 1058, "h": 307}], "szoveg": "11. Egy fahasáb vízen úszik úgy, hogy pont a magasságának feléig merül be a vízbe. Melyik esetben kell több munkát végeznünk? Ha a fahasábot egyenletesen (egyensúlyi helyzeteken keresztül) kiemeljük a vízből addig, míg az alsó lapja azonos magasságba nem kerül a vízszinttel, vagy ha egyenletesen (egyensúlyi helyzeteken keresztül) benyomjuk a vízbe, addig, amíg a felső lapja azonos magasságba nem kerül a vízszinttel? (A vízszint változásától eltekinthetünk.) A) Akkor, amikor benyomjuk. B) Akkor, amikor kiemeljük. C) Azonos lesz a munkavégzés a két esetben.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 12, "kepek": [{"src": "assets/exams/2026okt/I-12.png", "w": 1058, "h": 282}], "szoveg": "12. Két, egymástól d távolságban futó, párhuzamos vezetéken azonos irányban I áram folyik. Így az egyes vezetékek 1 méteres darabjára a másik vezeték által kifejtett erő 10 -10 N. Hogyan változik meg az erő nagysága, ha a vezetékek távolságát, valamint a bennük folyó áram erősségét is megduplázzuk? A) Az erő változatlanul 10 -10 N. B) Az erő megduplázódik, 2⸱10 -10 N lesz. C) Az erő a négyszeresére nő, 4⸱10 -10 N lesz. D) Az erő a felére csökken, 5⸱10 -11 N lesz.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 13, "kepek": [{"src": "assets/exams/2026okt/I-13.png", "w": 1058, "h": 317}], "szoveg": "13. Egy ideális tekercset és egy ohmikus ellenállást sorba kapcsolunk és váltófeszültségre kötünk. Egy másik esetben csak az ohmikus ellenállást kötjük ugyanarra a váltófeszültségre. Mikor szabadul fel több hő az ohmikus ellenálláson? A) Ha az ideális tekerccsel sorba van kötve, mert a tekercs induktív ellenállására eső teljesítménynek megfelelő hő is az ohmikus ellenálláson szabadul fel. B) Egyenlő a két esetben, mert a tekercsen nem szabadul fel hő, hiszen a tekercs ideális, a feszültség pedig a két esetben azonos. C) Ha nincs tekercs az áramkörben, mert az áramerősség ekkor nagyobb lesz.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 14, "kepek": [{"src": "assets/exams/2026okt/I-14.png", "w": 1058, "h": 223}], "szoveg": "14. Hogyan befolyásolná a Hold földkörüli pályáját, ha a Föld fekete lyuk sűrűségűre zsugorodna változatlan tömeg mellett? A) A Hold ebben az esetben belezuhanna a Földbe az extrém nagy gravitáció miatt. B) A Hold pályája nem változna. C) A Hold közelebb kerülne a Földhöz, így sebessége is növekedne.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 15, "kepek": [{"src": "assets/exams/2026okt/I-15.png", "w": 1058, "h": 392}], "szoveg": "15. Az Univerzum tágulásának bizonyítéka, hogy nagy léptékben a galaxisok többségének vöröseltolódása a Földtől vett távolságával arányosan nő. Egy ilyen galaxis például a 3C 295. Mit állíthatunk a mi galaxisunk, a Tejútrendszer fényéről a 3C 295 felől megfigyelve? A) A Tejútrendszer fénye kékeltolódást szenved, mert a 3C 295 felől nézve a Tejútrendszer ellentétes irányba mozog, mint a 3C 295 a Tejútrendszer felől nézve. B) A Tejútrendszer fénye a 3C 295 felől nézve nem fog frekvencia-eltolódást mutatni, mert a Tejútrendszer áll, a galaxisok minden irányban tőlünk távolodnak. C) A Tejútrendszer fénye a 3C 295 felől nézve vöröseltolódást mutat, mert a Tejútrendszer távolodik a 3C 295-től.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}], "II": {"bevezeto": [{"src": "assets/exams/2026okt/II-bevezeto.png", "w": 1058, "h": 151}], "temak": [{"nr": 1, "cim": "SpinLaunch", "kepek": [{"src": "assets/exams/2026okt/II-1.png", "w": 1058, "h": 1178}], "szoveg": "1. SpinLaunch Az amerikai SpinLaunch cég ősi technológiára alapozná műholdak Föld körüli pályára juttatását, ígérete szerint jelentősen olcsóbban, mint a hagyományos rakétatechnológia. A terv nem más, mint egy óriási centrifuga megépítése, amely hatalmas sebességre gyorsítva elhajítja a keringésre szánt műholdat tartalmazó kapszulát. A már megépült, „szub-orbitális gyorsítónak” nevezett tesztpéldány még csak kisöccse a tervezett berendezésnek, de a 33 m átmérőjű, vákuumkamrában forgó centrifuga 1600 km/h feletti kezdősebességgel, 10 000 m magasság fölé hajította a 200 kg tömegű próbaterhet. A következő, 100 m átmérőjű forgókarral tervezett példány már 2,2 km/s kezdősebességgel fogja terhét elhajítani. Mivel az alacsony légrétegekben tapasztalható légellenállás jelentősen korlátozza a praktikusan megvalósítható sebességet, a SpinLaunch-szerkezet valójában nem fog tudni egy teljesen passzív terhet Föld körüli pályára állítani. Ehelyett a tervek szerint a kellően magasra hajított teher a magasban begyújtaná saját rakétáit és a további emelkedést ezek biztosítanák. A koncepció hátránya, hogy a pörgés során hatalmas erő hat az űrbe juttatandó teherre, amit csak különlegesen megerősített berendezések viselhetnek el. Hogy a koncepció valóban életképesnek bizonyul-e, még a jövő titka. a) Ismertesse a Föld körül körpályán keringő űrhajóra ható erőket, a körpályán maradás feltételeit! b) Milyen elven működnek a hagyományos rakéták? Milyen tényezőktől függ a tolóerő, amit a rakéta ki tud fejteni? c) Mit nevezünk első kozmikus sebességnek? d) Eléri-e majd a tervezett nagyobb berendezés kilövési sebessége az első kozmikus sebességet? Hogyan tervezik a teher űrbe juttatását végrehajtani? e) Elképzelhető-e, hogy embert is ezzel a technológiával juttassunk az űrbe? Válaszát indokolja! f) Milyen tényezők befolyásolják, hogy egy adott testre mekkora légellenállási erő hat? Hogyan változnak ezek a tényezők egy hagyományos rakétaút során, amíg a rakéta a Földről felszállva eljut az űrig? Miben más a helyzet a SpinLaunch-cég koncepciójánál? g) Mekkora (hány g) centripetális gyorsulást kellett elviselnie a tesztpéldány által elhajított tehernek a pörgés során?", "utmutato": [{"src": "assets/exams/2026okt/II-1-ut.png", "w": 1058, "h": 1308}]}, {"nr": 2, "cim": "A gyorsulásmérő", "kepek": [{"src": "assets/exams/2026okt/II-2.png", "w": 1058, "h": 1441}], "szoveg": "2. A gyorsulásmérő Ma már minden mobiltelefonban van gyorsulásmérő, ami egy mikroszkopikus tömeg–rugó rendszeren alapul. Ezen gyorsulásmérők egyik fajtája kapacitásváltozások mérésén alapszik, rendkívül leegyszerűsített modelljét mutatja a következő ábra. A kör egy olyan testet mutat, amit egy rugó rögzít az eszköz dobozához. A bal oldalon lévő két párhuzamos lemez egy síkkondenzátort jelöl. A kondenzátor jobb oldali fegyverzetét a kör alakú testhez erősítették. Ha az a tárgy (például a mobiltelefon), amiben a gyorsulásmérő van, jobbra gyorsul, akkor a rugó megnyúlik, hiszen a kör alakú testet is gyorsítani kell, és így a síkkondenzátor lemezei közötti távolság lecsökken, ahogy ezt a jobb oldali ábra mutatja. A síkkondenzátor lemezeihez elektromos vezetékek csatlakoznak, így a síkkondenzátor egy gondosan megtervezett áramkör részévé válik. Az áramkör a síkkondenzátor kapacitásának változását feszültségjellé alakítja, amiből az eszköz gyorsulása meghatározható. A telefonokban általában egyetlen chipben három gyorsulásmérő van, melyek három egymásra merőleges irányban mérik a telefon gyorsulását: a , a , a . A függőleges irányban elhelyezkedő gyorsulásmérőben a rugó a testre ható gravitáció x y z miatt még abban az esetben is megnyúlik, ha az eszköz a Földhöz képest nem gyorsul. Ennek köszönhetően a készülék meg tudja határozni saját elhelyezkedését a függőleges irányhoz képest. A gyorsulásmérő adatait a telefon számos funkcióban használja, például képernyőforgatásnál vagy lépésszámlálásnál. a) Mit nevezünk kondenzátornak? Mutassa be a síkkondenzátor felépítését, adja meg jellemző adatait! Hogyan függ a síkkondenzátor kapacitása a geometriai adatoktól, illetve lemezek közötti közeg dielektromos állandójától? b) Hogyan változik a sematikus ábrán látható síkkondenzátor kapacitása, ha a gyorsulásmérő jobbra kezd gyorsulni? Válaszát indokolja! c) Hogyan méri a gravitáció irányát és nagyságát az elrendezés nyugalmi állapotban? d) Miért kell a gyorsulásmérőben létrejövő rezgést megfelelő csillapítással elkerülni? A csillapításhoz súrlódásos vagy közegellenállásos csillapítást célszerű használni? Válaszát indokolja! e) Miért alkalmas az eszköz lépésszámlálásra? f) Mekkora gyorsulást mutat egy leejtett mobil, miközben a levegőben zuhan? g) Egy gyorsulásmérő érzékenysége (a legkisebb gyorsulás, amit kimutat) 0,001ꞏg, ekkor a kondenzátor lemeztávolságának megváltozása 20 pm. Mekkora a rugóállandó, ha a mozgó tömeg nagysága 10 µg? (1 pm = 10 -12 m, 1 µg = 10 -9 kg, g = 9,8 m/s 2 )", "utmutato": [{"src": "assets/exams/2026okt/II-2-ut.png", "w": 1058, "h": 1470}]}, {"nr": 3, "cim": "Prizma", "kepek": [{"src": "assets/exams/2026okt/II-3.png", "w": 1058, "h": 1441}], "szoveg": "3. Prizma A szivárványról azt hiszi a köznép, hogy annak végei mindenkor valami tóban, vagy folyó vízben állnak, s abból vizet szívnak fel a levegőbe, s annakutána abból lesz az esső. Erre a tévelygésre úgy látszik, a szivárványnak neve tsalta az embereket, melly a szívástól vagy szivárgástól neveztetvén, azt gondolták, hogy vizet szív fel. Fábián József: Természeti tudomány a köznépnek 1803 Veszprém a) Ismertesse a fény törésének törvényét, az azt leíró mennyiségeket! b) Mutassa be ábra segítségével a törvényt optikailag sűrűbb közegből optikailag ritkább közegbe, valamint optikailag ritkább közegből optikailag sűrűbb közegbe való átlépés esetén! c) Keressen természeti példát a fénytörésre! d) Ismertesse a teljes visszaverődés jelenségét! e) Adjon meg egy gyakorlati példát a teljes visszaverődésre! f) Mutassa be rajzon az üvegprizma fénytörését monokromatikus fényre! g) Ismertesse a „fehér fény” fogalmát! h) Ismertesse a prizma kapcsán a diszperzió jelenségét és annak értelmezését! i) Hasonlítsa össze a piros és kék fényt hullámhossz és frekvencia szerint! j) Mutassa be és magyarázza a piros és kék színű fény jellemzőinek felhasználásával, hogy hogyan helyezkednek el a fehér fény összetevői az üvegprizma mögött! k) Említsen meg egy másik gyakorlati eljárást vagy jelenséget, amikor a fehér fény összetevőire bomlik!", "utmutato": [{"src": "assets/exams/2026okt/II-3-ut.png", "w": 1058, "h": 1441}]}], "kifejtes": [{"src": "assets/exams/2026okt/II-kifejtes.png", "w": 1058, "h": 1417}]}, "III": [{"nr": 1, "kepek": [{"src": "assets/exams/2026okt/III-1.png", "w": 1058, "h": 536}], "szoveg": "1. Ha atomos hidrogént ionizálunk, akkor többnyire protonokat kapunk, de mivel kis százalékban a mintában megtalálható a hidrogén deutérium nevű izotópja is, ezért a protonok mellett lesznek deuteron nevű részecskéink is, melyek a deutérium atommagjai, egy protonból és egy neutronból álló részecskék. a) Mekkora mozgási energiára tesznek szert a kezdetben álló protonok és deuteronok 100 kV gyorsítófeszültség hatására? A választ adja meg elektronvolt és joule mértékegységben is! b) Mekkora sebességre gyorsulnak fel a kezdetben álló protonok és deuteronok 100 kV gyorsítófeszültség hatására? c) Ha a részecskéket a mágneses indukcióvonalakra merőlegesen homogén mágneses térbe vezetjük, akkor a belépéstől számítva mekkora távolságra kell elhelyeznünk detektorokat az ábrán látható szaggatott vonal mentén, hogy megszámlálhassuk a részecskéket? A mágneses indukció nagysága 0,5 T. (e = 1,610 -19 C, m = 1,6710 -27 kg, m  2  m ) p D p", "pont": 11, "reszek": [{"betu": "a", "pont": 2}, {"betu": "b", "pont": 4}, {"betu": "c", "pont": 5}], "megoldas": [{"src": "assets/exams/2026okt/III-1-ut.png", "w": 1058, "h": 1213}]}, {"nr": 2, "kepek": [{"src": "assets/exams/2026okt/III-2.png", "w": 1058, "h": 1058}], "szoveg": "2. Egy mérés során egy fotocella katódját három különböző frekvenciájú fénnyel világítjuk meg. A fotocellához egy kondenzátort kapcsoltunk, melynek feszültségét egy érzékeny elektrosztatikus voltmérő méri az ábrán látható módon. Hosszabb idejű megvilágítás után leolvassuk a voltmérőn megjelenő telítési értéket. A kapott adatpárokat a következő táblázat tartalmazza: f (Hz) 5  10 14 7,5  10 14 10 15 U (V) 1 2 3 a) Magyarázza meg, hogy miért áll be egy maximális telítési feszültségérték a kondenzátoron! b) Ábrázolja grafikusan a kondenzátor telítési feszültségét a megvilágítás frekvenciájának a függvényében! c) A grafikonról olvassa le a fotocella katódanyagának határfrekvenciáját! d) A grafikonról olvassa le a fotokatód anyagára jellemző kilépési munkát elektronvolt mértékegységben, majd adja meg ezt az értéket joule-ban is! (Az elemi töltés e = 1,6ꞏ10 -19 C.) U (V) 3 2 1 0 f (10 15 Hz) 0,5 1 -1", "pont": 10, "reszek": [{"betu": "a", "pont": 2}, {"betu": "b", "pont": 2}, {"betu": "c", "pont": 3}, {"betu": "d", "pont": 3}], "megoldas": [{"src": "assets/exams/2026okt/III-2-ut.png", "w": 1058, "h": 1436}]}, {"nr": 3, "kepek": [{"src": "assets/exams/2026okt/III-3.png", "w": 1058, "h": 350}], "szoveg": "3. Egy villanybojler hasznos térfogata 100 liter, a fűtőszálának teljesítménye 2 kW. A hálózatból 10 °C-os vizet engedünk bele, bekapcsoljuk, és a bojler addig fűti, amíg a bojler és a tartalma 60 °C-os nem lesz. A bojlerben a használat során sok vízkő rakódott le. Azt tapasztaljuk, hogy a teli bojler tömege 110 kg-mal több, mint az üres bojler gyár által megadott tömege. a) Mekkora a bojlerben lévő vízkő tömege és térfogata? b) Mennyi a vízkő fajhője, ha a fűtőszál 175 perc alatt melegíti fel 10 °C-ról 60 °C-ra bojler tartalmát, az üres acéltartály 26 kg tömegű? (A víz fajhője c = 4,184 kJ/(kgꞏ°C), az acél fajhője c = 0,46 kJ/(kgꞏ°C) a vízkő víz acél sűrűsége 3 kg/l.)", "pont": 13, "reszek": [{"betu": "a", "pont": 5}, {"betu": "b", "pont": 8}], "megoldas": [{"src": "assets/exams/2026okt/III-3-ut.png", "w": 1058, "h": 1436}]}, {"nr": 4, "kepek": [{"src": "assets/exams/2026okt/III-4.png", "w": 1058, "h": 473}], "szoveg": "4. Súrlódásmentes, vízszintes, légpárnás asztalon álló céltárgyba egy kilövőszerkezet azonos tömegű és azonos sebességű, vízszintesen becsapódó lövedékeket lő. A lövedékek a céltárgyban maradnak. Megmérjük a céltárgy sebességét a becsapódás után. Minden lövés után megállítjuk a céltárgyat, és újabb lövedéket lövünk a megnövekedett tömegű céltárgyba. Az ütközési folyamat mindig egy egyenes mentén történik. A következő táblázat a lövések számát és a céltárgy lövés utáni sebességét mutatja, azonban két adat hiányzik: A lövés sorszáma 1 2 3 4 A céltárgy sebessége a becsapódás után 2 1,2 (m/s) a) Az első lövés előtt hányszor nagyobb volt a céltárgy tömege, mint a lövedék tömege? b) Mekkora sebességű lövedék csapódott a céltárgyba? c) Mekkora a céltárgy sebessége a 2. és a 4. lövés után?", "pont": 13, "reszek": [{"betu": "a", "pont": 6}, {"betu": "b", "pont": 3}, {"betu": "c", "pont": 4}], "megoldas": [{"src": "assets/exams/2026okt/III-4-ut.png", "w": 1058, "h": 1168}]}]}, {"id": "2026maj", "cim": "2026. május", "datum": "2026. május 19.", "ido": 240, "kod": null, "forras": "Oktatási Hivatal – emelt szintű fizika írásbeli feladatlap és javítási-értékelési útmutató", "I": [{"nr": 1, "kepek": [{"src": "assets/exams/2026maj/I-01.png", "w": 1058, "h": 327}], "szoveg": "1. Egy egyenes vonal mentén mozgó testre állandó nagyságú és irányú eredő erő hat. Az alábbiak közül melyik grafikon mutathatja a test helyét az idő függvényében? A) Csak az I. grafikon lehet. B) Csak a II. grafikon lehet C) Mindkét grafikon lehet. D) Egyik grafikon sem lehet.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 2, "kepek": [{"src": "assets/exams/2026maj/I-02.png", "w": 1058, "h": 226}], "szoveg": "2. Két azonos tömegű és anyagú fűtőszálunk van; az egyik háromszor hosszabb, mint a másik. Ha azonos feszültségre kapcsoljuk a két fűtőszálat, melyik fűtőszál fűtőteljesítménye lesz a nagyobb? A) A hosszabbé. B) A rövidebbé. C) Azonos lesz a két fűtőteljesítmény.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 3, "kepek": [{"src": "assets/exams/2026maj/I-03.png", "w": 1058, "h": 166}], "szoveg": "3. Mit állíthatunk a Doppler-effektusról? A) Csak akkor figyelhető meg, ha a hullámforrás mozog és a megfigyelő áll. B) Csak akkor figyelhető meg, ha a megfigyelő mozog és a hullámforrás áll. C) Mindkét esetben megfigyelhető.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 4, "kepek": [{"src": "assets/exams/2026maj/I-04.png", "w": 1058, "h": 364}], "szoveg": "4. Egy mozgó test álló céltárgyba ütközik. Lehetséges-e, hogy az ütközés után a céltárgy lendülete nagyobb lesz, mint a vele ütköző test lendülete volt? (A testek ütközés előtt és után egy egyenes mentén haladnak.) A) Csak akkor lehetséges, ha a mozgó test tömege kisebb a céltárgy tömegénél. B) Csak akkor lehetséges, ha a mozgó test tömege megegyezik a céltárgy tömegével. C) Csak akkor lehetséges, ha a mozgó test tömege nagyobb a céltárgy tömegénél. D) Semmikor sem adhat át a saját lendületénél többet a mozgó test a céltárgynak.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 5, "kepek": [{"src": "assets/exams/2026maj/I-05.png", "w": 1058, "h": 433}], "szoveg": "5. Elegendően mély vízbe úszó sűrűségmérőt teszünk. A víz tetejére a víznél kisebb sűrűségű olajat rétegezünk fokozatosan. Hogy mozdul el az úszó sűrűségmérő az edényhez képest, és hogyan változik eközben a sűrűségmérő folyadékból kilógó hossza? A) A sűrűségmérő emelkedik az edényhez képest, és a folyadékból kilógó részének hossza nő. B) A sűrűségmérő emelkedik az edényhez képest, de a folyadékból kilógó részének hossza csökken. C) A sűrűségmérő lefelé mozdul az edényhez képest, de a folyadékból kilógó részének hossza nő. D) A sűrűségmérő lefelé mozdul az edényhez képest, és a folyadékból kilógó részének hossza csökken.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 6, "kepek": [{"src": "assets/exams/2026maj/I-06.png", "w": 1058, "h": 295}], "szoveg": "6. A lap síkjára merőlegesen kifelé mutató homogén mágneses mezőben egy kör alakú drótvezető helyezkedik el. Milyen irányú áram indul el a vezetőben, ha azt a nyilak irányában, két oldalról összenyomjuk? A) Az óramutató járásával ellentétes irányban fog folyni az áram a vezetőben. B) Nem fog áram folyni a vezetőben. C) Az óramutató járásával megegyező irányban fog folyni az áram a vezetőben.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 7, "kepek": [{"src": "assets/exams/2026maj/I-07.png", "w": 1058, "h": 327}], "szoveg": "7. Egy rúd két homogén, egyforma keresztmetszetű, de eltérő hosszúságú rúddarabból áll. Az egyik rúddarab kétszer olyan hosszú, mint a másik. Ha az így kialakított rudat a két rúddarab illesztési pontjában alátámasztjuk, az egyensúlyban lesz. Mit állíthatunk a két rúddarab sűrűségének arányáról? A) A sűrűségek aránya 1:1 B) A sűrűségek aránya 1:2 C) A sűrűségek aránya 1:3 D) A sűrűségek aránya 1:4", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 8, "kepek": [{"src": "assets/exams/2026maj/I-08.png", "w": 1058, "h": 283}], "szoveg": "8. Egy elzárt ideális gázt két különböző folyamatban nyomunk össze. Először izobár folyamatban összenyomjuk a kezdeti térfogata felére, utána pedig az eredeti kezdőállapotból kiindulva izoterm folyamatban nyomjuk össze, szintén a kezdeti térfogat felére. Melyik folyamatban kell nagyobb munkát végeznünk? A) Az izobár folyamatban. B) Az izoterm folyamatban. C) Egyforma a két munkavégzés. D) Nem lehet eldönteni, a kezdőállapot pontos paramétereitől függ.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 9, "kepek": [{"src": "assets/exams/2026maj/I-09.png", "w": 1058, "h": 410}], "szoveg": "9. Egy csillag körüli – az ábrának megfelelően – ellipszispályán keringő bolygó mozgásának irányát a nyíl jelzi. A bolygó mozgását közvetlenül a rajzon látható kiindulási helyzetet követően figyeljük meg. Az alábbi, bolygóra jellemző mennyiségek közül melyikről mondhatjuk azt el, hogy értéke a megfigyeléskor növekszik? (A rendszert más égitestek nem befolyásolják.) A) A bolygó pályamenti sebessége. B) A bolygó területi sebessége. C) A bolygó összes mechanikai energiája. D) A bolygó potenciális energiája a csillag gravitációs terében.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 10, "kepek": [{"src": "assets/exams/2026maj/I-10.png", "w": 1058, "h": 372}], "szoveg": "10. Homogén mágneses mezőn vezetünk át α-, β - - és γ-részecskék alkotta sugárnyalábot az indukcióvonalak irányára merőlegesen. Mit állíthatunk a nyalábok eltérüléséről? A) Az α-sugárzás nem térül el, a β  - és a γ-sugárzás eltérül, egymással ellentétes irányban. B) Az β  -sugárzás nem térül el, a α- és a γ-sugárzás eltérül, az α-sugárnyaláb kevésbé görbül el, mint a γ. C) Az γ-sugárzás nem térül el, az α- és a β  -sugárzás eltérül, egymással ellentétes irányban. D) Mindhárom sugárnyaláb eltérül, az α- és a γ-sugárzás azonos, míg a β  - sugárzás velük ellentétes irányban.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 11, "kepek": [{"src": "assets/exams/2026maj/I-11.png", "w": 1058, "h": 282}], "szoveg": "11. Két autó két különböző sugarú, vízszintes körpályán jár egyenletesen körbe. A piros autó pályájának sugara kétszer akkora, mint a kék autóé. A két autó azonos idő alatt tesz meg egy kört. Melyik autó esetében van szükség nagyobb tapadási súrlódási együtthatóra a kerék és az aszfalt között, hogy ne csússzon meg az autó? A) A piros autó esetében. B) A kék autó esetében. C) A két autó esetében egyforma nagy tapadási együtthatóra van szükség. D) A válasz csak az autók tömegének ismeretében adható meg.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 12, "kepek": [{"src": "assets/exams/2026maj/I-12.png", "w": 1058, "h": 293}], "szoveg": "12. A következő három állítás az elektromos és a gravitációs erőhatásokat hasonlítja össze. Melyik állítás igaz? A) Két pontszerű töltött részecske kölcsönhatása során bármelyik részecskére ható Coulomb-erő iránya mindig megegyezik a gravitációs erő irányával. B) Két pontszerű töltött részecske között fellépő Coulomb-erő és gravitációs erő nagysága egyaránt fordítottan arányos a részecskék közötti távolság négyzetével. C) A Nap és a Jupiter között ható Coulomb-erő nagyobb, mint ugyanezen két égitest között fellépő gravitációs erő.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 13, "kepek": [{"src": "assets/exams/2026maj/I-13.png", "w": 1058, "h": 216}], "szoveg": "13. Megváltoztathatják-e egy pontrendszer mozgási energiáját a belső, illetve a külső erők? A) Csak a belső erők változtathatják meg. B) Csak a külső erők változtathatják meg. C) A belső és a külső erők egyaránt megváltoztathatják. D) Sem a belső, sem a külső erők nem tudják megváltoztatni.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 14, "kepek": [{"src": "assets/exams/2026maj/I-14.png", "w": 1058, "h": 594}], "szoveg": "14. Két vízszintes gumikötélen hullámokat keltünk. A bal oldali kötélen állóhullámot hozunk létre, a jobb oldalin haladó hullámot. Az ábra ugyanabban a pillanatban mutatja a két gumikötél pontjainak y kitérését a kötélen elfoglalt x helyének függvényében. Mit állíthatunk a kötelek A, B illetve C, D pontjait jellemző sebességvektorokról? A) A és B pont sebességvektorai azonos irányúak, valamint a C és D pont sebességvektorai is azonos irányúak. B) A és B pont sebességvektorai azonos irányúak, viszont a C és D pont sebességvektorai ellentétes irányúak. C) A és B pont sebességvektorai ellentétes irányúak, viszont a C és D pont sebességvektorai azonos irányúak. D) A és B pont sebességvektorai ellentétes irányúak, valamint a C és D pont sebességvektorai is ellentétes irányúak.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 15, "kepek": [{"src": "assets/exams/2026maj/I-15.png", "w": 1058, "h": 275}], "szoveg": "15. A Föld forgási és keringési iránya azonos körüljárású. A Föld abban az irányban kering, mint amilyen irányban forog. Egy ember a Föld azon pontján áll, amelynek Naphoz képesti sebessége a legnagyobb a földfelszín pontjai közül. Milyen napszak van ebben a pontban? A) Hajnal. B) Nappal. C) Alkony. D) Éjszaka.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}], "II": {"bevezeto": [{"src": "assets/exams/2026maj/II-bevezeto.png", "w": 1058, "h": 150}], "temak": [{"nr": 1, "cim": "A fémkereső detektor", "kepek": [{"src": "assets/exams/2026maj/II-1.png", "w": 1058, "h": 1139}], "szoveg": "1. A fémkereső detektor A hétköznapi életben több helyen találkozhatunk fémkereső detektorokkal. Ilyen például a repülőterek beléptető kapuja. De sokan járják például a tengerpartokat elhagyott fémtárgyak, pénzérmék után kutatva. A detektorok felépítése és fajtája nagyon sokféle lehet. A detektorok fontos része egy úgynevezett gerjesztőtekercs, amely változó mágneses teret hoz létre a vizsgálandó térrészben. Ha a változó mágneses tér fémet ér, akkor a fém erre elektromágneses hullám formájában válaszjelet sugároz, amit többnyire egy vevőtekerccsel észlelhetünk. A gerjesztőtekercs általában 5–15 kHz közötti frekvenciákat használ, az alacsony frekvenciájú hullám mélyebben a földbe hatol, de kisebb tárgyakat (pl. érmék) nem képes feltárni, mert a gerjesztőtekercs frekvenciájának csökkenésével keletkező örvényáramok is gyengébbek lesznek. Általában elmondható, hogy a vizsgált térrészben lévő anyagok vezetőképessége és relatív mágneses permeabilitása alapján a különböző anyagok különböző erősségű és jellegű válaszjeleket adnak. A válaszjelek szűrése, erősítése, feldolgozása gyors áramkörök segítségével történik, sokszor fény- vagy hangjelekké alakítják át a fémkeresők az információt. a) Mutassa be az elektromágneses indukciót leíró Faraday-törvényt! b) Mikor jönnek létre egy nyugvó tárgyban örvényáramok? Mit mondhatunk az örvényáramok irányáról? Ismertesse Lenz törvényét általánosságban! c) Ismertesse vázlatosan, hogy jön létre az elektromágneses válaszjel a fémkereső által megtalált fém tárgyban! d) Általában az egybefüggő, tömbszerű, nagyobb tárgyak könnyebben detektálhatók, mint a vékony szálakból vagy vékony, szigetelt rétegekből állók. Adjon magyarázatot a jelenségre! e) Minél távolabb van a fémkereső detektor tekercse a fémtárgytól, annál kisebb jelet észlel a kereső. Milyen okai lehetnek ennek? f) A talajban lévő üvegtárgyakra nem jelez a detektor, de néha a nedves föld is ad gyenge hamis jelet. Miért? g) Alacsonyabb frekvenciájú gerjesztés gyengébb jeleket eredményez egy adott fémtárgy esetében. Miért? h) Milyen értékek között változhat a szokásos gerjesztőtekercsek által használt elektromágneses hullám hullámhossza?", "utmutato": [{"src": "assets/exams/2026maj/II-1-ut.png", "w": 1058, "h": 1353}]}, {"nr": 2, "cim": "A Ciaran-vihar tombolása", "kepek": [{"src": "assets/exams/2026maj/II-2.png", "w": 1058, "h": 1441}], "szoveg": "2. A Ciaran-vihar tombolása „Britek milliói voltak kénytelenek 2023 novemberében pocsék ízű teát inni a Ciaran-vihar tombolása alatt” – erre következtet a Guardian egy friss kutatás alapján, melynek szerzői a víz forráspontjáról készítettek méréseket a vihar napján Angliában. Az Egyesült Királyságban lévő Readingi Egyetem meteorológusainak friss tanulmánya azt állapította meg, hogy a városban a vihar reggelén 100 °C helyett mindössze 98 °C volt a víz forráspontja. A 2023. november elején átvonuló viharnak Európában több halálos áldozata is volt, a helyenként 160–190 kilométer/órás széllökésekkel és erős esőzésekkel járó ciklon több ezer francia és brit háztartásban okozott áramkimaradást. (A Telex cikkének nyomán.) a) Mit nevezünk telített vízgőznek? b) Ismertesse a forrás jelenségét, adja meg a forráspont nyomásfüggésének magyarázatát! c) A vihar során fellépő erős széllökések nyomáscsökkenést okozhatnak. Ha egy áramló közeg keresztmetszete csökken, akkor hogyan változik az áramlás sebessége és a közegbeli nyomás? d) A csatolt táblázat alapján állapítsa meg a Ciaran-vihar hatására bekövetkező nyomáscsökkenés mértékét! e) A nyugalomban lévő levegő nyomásának csökkenését és ennek következtében a víz forráspontjának csökkenését a magas hegyek között is megfigyelhetjük. Mi a magyarázata annak, hogy a levegő nyomása a tengerszint feletti magasság függvényében csökken? Ez a csökkenés nem egyenesen arányos a magassággal. Miért? f) Egy erős széllökés hatására egy ház tetőablakainak külső oldalán 1500 Pa nyomáscsökkenést mérhetünk. Mekkora erő hat ilyenkor egy 80 cm-szer 150 cm-es ablakra, ha a ház belsejében normál légköri nyomás van? Telített vízgőz nyomása különböző hőmérsékleteken hőmérséklet (°C) nyomás (kPa) 100 101,3 99 97, 8 98 94,3 97 90,9 96 87,7 .", "utmutato": [{"src": "assets/exams/2026maj/II-2-ut.png", "w": 1058, "h": 1470}]}, {"nr": 3, "cim": "A Hold mozgása", "kepek": [{"src": "assets/exams/2026maj/II-3.png", "w": 1058, "h": 1441}], "szoveg": "3. A Hold mozgása „Ez a besötétedés természetesen csak a hold újságakor esetik meg, mert csak akkor lehet a nap és a föld közt a hold, de nem minden hold újulásakor történhetik meg, mert a hold újulása csak azt kívánja egy líneán légyen a hold a nappal, mely minden holdnapban rendesen megtörténik, de a nap fogyatkozása még ezen kívül azt is megkívánja, hogy a hold a gomboknál légyen, vagy közel hozzájuk, mely minden holdnapban meg nem eshetik.” Varga Márton: A csillagos égnek és a Föld golyóbissának az ő tüneményeivel együtt való természeti előadás és megismértetése 1809, Nagyvárad. a) Körülbelül mennyi idő alatt kerüli meg a Hold a Földet és a Napot? b) Mi a magyarázata annak, hogy a Hold mindig ugyanazt az oldalát mutatja a Föld felé? c) Miért látunk holdfázisokat? Térjen ki arra, hogy mekkora az egyes holdfázisok idején a Hold megvilágított része! d) Ismertesse és értelmezze a napfogyatkozás jelenségét! e) Milyen holdfázis van napfogyatkozáskor? f) A napfogyatkozások során lehetséges, hogy a Nap teljes mértékben takarásban van, egyáltalán nem látszik. Van olyan eset is, amikor a Nap fényes pereme körben, gyűrűszerűen veszi körül a sötét, leárnyékolt részt. Mi a különbség az égitestek elhelyezkedésében ebben a két esetben? g) A Naprendszer mely bolygói tudnak (a Földről szabad szemmel észrevehetetlen) napfogyatkozást okozni? Milyen tényezőkön múlik, hogy mekkora egy égitest árnyéka a Napon? h) Értelmezze a holdfogyatkozás létrejöttét! i) Milyen holdfázis van holdfogyatkozáskor? j) Teljes holdfogyatkozáskor is látjuk halványan és vörösen a Holdat a Földről. Miért?", "utmutato": [{"src": "assets/exams/2026maj/II-3-ut.png", "w": 1058, "h": 1441}]}], "kifejtes": [{"src": "assets/exams/2026maj/II-kifejtes.png", "w": 1058, "h": 1417}]}, "III": [{"nr": 1, "kepek": [{"src": "assets/exams/2026maj/III-1.png", "w": 1058, "h": 396}], "szoveg": "1. Egy szobadísz nagyon könnyű pálcákból és a pálcákon függő testekből áll. Az elrendezést az ábra mutatja, amelyről leolvasható a különböző felfüggesztési pontok távolsága. A pálcák vízszintes helyzetben, egyensúlyban vannak. Tudjuk, hogy a (3. számú) csillag tömege m  48 g . Mekkora a 3 többi test tömege?", "pont": 11, "reszek": [], "megoldas": [{"src": "assets/exams/2026maj/III-1-ut.png", "w": 1058, "h": 1184}]}, {"nr": 2, "kepek": [{"src": "assets/exams/2026maj/III-2.png", "w": 1058, "h": 264}], "szoveg": "2. Egy kórházi vizsgálat során a páciens vérének térfogatát a következő eljárással vizsgálják meg: Először 10 ml térfogatú, 1 MBq aktivitású, 3 óra felezési idejű radioaktív izotópot tartalmazó oldatot fecskendeznek a véráramba, majd várnak 6 órát, hogy az oldat a vérben teljesen elkeveredjen. Ezután levesznek a beteg véréből 10 ml-t, és megmérik a levett vérminta aktivitását. Azt tapasztalják, hogy ez 500 Bq. a) Mennyi lenne az oldat aktivitása 6 óra elteltével, ha nem fecskendezik be a páciensbe? b) Körülbelül mekkora a beteg vérének össztérfogata, ha feltehetjük, hogy az eredeti oldat teljesen egyenletesen oszlik el a vérben hat óra elteltével?", "pont": 11, "reszek": [{"betu": "a", "pont": 4}, {"betu": "b", "pont": 7}], "megoldas": [{"src": "assets/exams/2026maj/III-2-ut.png", "w": 1058, "h": 1436}]}, {"nr": 3, "kepek": [{"src": "assets/exams/2026maj/III-3.png", "w": 1058, "h": 357}], "szoveg": "3. Az R = 100 Ω, az R = 200 Ω, az 1 2 R = 300 Ω és az R = 400 Ω nagyságú 3 4 ellenállásokból, egy 12 V-os, ideális telepből, valamint egy K kapcsolóból az ábrán látható áramkört állítjuk össze. Az áramkörbe egy ideális feszültségmérő műszert kapcsolunk. a) Mit mutat a voltmérő a kapcsoló nyitott állásánál? b) Mit mutat a voltmérő a kapcsoló zárt állásánál?", "pont": 13, "reszek": [{"betu": "a", "pont": 5}, {"betu": "b", "pont": 8}], "megoldas": [{"src": "assets/exams/2026maj/III-3-ut.png", "w": 1058, "h": 1436}]}, {"nr": 4, "kepek": [{"src": "assets/exams/2026maj/III-4.png", "w": 1058, "h": 264}], "szoveg": "4. Egy hőerőgép minden ciklusban 1,7 kJ energiát vesz fel a magas hőmérsékletű kazánból, és 1,2 kJ energiát ad le az alacsony hőmérsékletű hűtőnek. a) Mennyi hasznos munkát végez ciklusonként a hőerőgép? b) Mekkora a hatásfoka? c) Mekkora a hasznos teljesítménye, ha tudjuk, hogy a ciklusok 0,3 másodpercenként ismétlődnek? Számításaink során a súrlódási veszteségektől tekintsünk el.", "pont": 12, "reszek": [{"betu": "a", "pont": 4}, {"betu": "b", "pont": 4}, {"betu": "c", "pont": 4}], "megoldas": [{"src": "assets/exams/2026maj/III-4-ut.png", "w": 1058, "h": 935}]}]}, {"id": "2025okt", "cim": "2025. október", "datum": "2025. október 27.", "ido": 240, "kod": null, "forras": "Oktatási Hivatal – emelt szintű fizika írásbeli feladatlap és javítási-értékelési útmutató", "I": [{"nr": 1, "kepek": [{"src": "assets/exams/2025okt/I-01.png", "w": 1058, "h": 311}], "szoveg": "1. Egy 2 kg tömegű fahasábot helyezünk egy asztal vízszintes felületére, majd a testre az ábrán látható külső erőket fejtjük ki. A fahasáb és az asztal felülete közötti csúszási és tapadási súrlódási együttható egyaránt 0,3. Merre gyorsul a fahasáb? A) A hasáb balra gyorsul. B) A hasáb jobbra gyorsul. C) A hasáb nem gyorsul.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 2, "kepek": [{"src": "assets/exams/2025okt/I-02.png", "w": 1058, "h": 436}], "szoveg": "2. Egy üvegpohárban a folyadék az ábrának megfelelően helyezkedik el. Hogyan helyezkedik el a pohárral azonos anyagú kapilláris üvegcsövek rendszerében ez a folyadék? A) A bal oldali ábrának megfelelően. B) A középső ábrának megfelelően. C) A jobb oldali ábrának megfelelően.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 3, "kepek": [{"src": "assets/exams/2025okt/I-03.png", "w": 1058, "h": 339}], "szoveg": "3. Hosszú, egyenes vezetőben 50 A áram folyik. A mágneses mező a vezetőre merőleges és 0,2 T nagyságú, ahogy ezt az ábra mutatja. Mekkora és milyen irányú erő hat a vezető 1 méter hosszúságú I darabjára? B A) 250 N, az ábra síkjában. B) 10 N, az ábra síkjában. C) 250 N, az ábra síkjára merőlegesen. D) 10 N, az ábra síkjára merőlegesen.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 4, "kepek": [{"src": "assets/exams/2025okt/I-04.png", "w": 1058, "h": 461}], "szoveg": "4. Egy v sebességgel, vízszintesen mozgó, m = 0,1 kg tömegű kiskocsi h magasságig jut 0 a súrlódásmentes emelkedőn, mielőtt megállna. Ezután a vízszintes pályaszakaszon a kiskocsi útjába egy nyugvó, M = 0,3 kg tömegű, szintén súrlódás nélkül mozgó dobozt helyezünk, amivel a kiskocsi tökéletesen rugalmatlanul ütközik. Milyen magasra jutnak ugyanazon az emelkedőn az ütközés után? A) h/2 magasra. B) h/4 magasra. C) h/8 magasra. D) h/16 magasra.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 5, "kepek": [{"src": "assets/exams/2025okt/I-05.png", "w": 1058, "h": 348}], "szoveg": "5. Egy vékony fénysugár kék és vörös fény keverékéből áll. Ez a fénysugár 60-os beesési szöggel egy vastag, sík-párhuzamos (plán-parallel) üveglapra esik, és azon áthalad. Amikor a fény kilép az üveglap túloldalán, A) a két színes fénynyaláb különböző pontokban jelenik meg, és különböző irányokba halad. B) a két színes fénynyaláb különböző pontokban jelenik meg, és párhuzamosan halad. C) a két színes fénynyaláb azonos pontban jelenik meg, és különböző irányokba halad. D) a két színes fénynyaláb azonos pontban jelenik meg, és párhuzamosan halad.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 6, "kepek": [{"src": "assets/exams/2025okt/I-06.png", "w": 1058, "h": 315}], "szoveg": "6. Egy szél által kimozdított cserépdarab lecsúszik egy íves tetőn, és egy ponton leválik róla. Mekkora a gyorsulása ebben a pillanatban? (A közegellenállást hanyagoljuk el!) A) Nagyobb, mint g a centripetális gyorsulás miatt. B) Kisebb, mint g, a nyomóerő miatt. C) Éppen g, mert szabadon esik.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 7, "kepek": [{"src": "assets/exams/2025okt/I-07.png", "w": 1058, "h": 250}], "szoveg": "7. Egy precíz, kétkarú patikamérleg egyik serpenyőjében ólomgolyó van, a másik serpenyőjében egy tömör, kis sűrűségű műanyagból készült golyó. A mérleg pontosan egyensúlyban van. Mi történik, ha a mérleget üvegbúra alá helyezzük, és kiszivattyúzzuk a levegőt? A) A mérleg továbbra is pontosan egyensúlyban lesz. B) A mérleg elbillen, az ólomgolyó lejjebb kerül. C) A mérleg elbillen, a műanyag golyó lejjebb kerül.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 8, "kepek": [{"src": "assets/exams/2025okt/I-08.png", "w": 1058, "h": 286}], "szoveg": "8. Egy állandó térfogatú tartály 4 mol ideális gázt tartalmaz 2 atmoszféra nyomáson és 27 C hőmérsékleten. A tartályon lévő biztonsági szelep akkor nyit ki, ha a tartályban lévő nyomás meghaladja a 2 atmoszférát. Hány mol gáz hagyja el a tartályt a biztonsági szelepen keresztül, ha a gáz hőmérsékletét 127 C-ra növeljük? A) 0 mol. B) 1 mol. C) 2 mol. D) 3 mol.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 9, "kepek": [{"src": "assets/exams/2025okt/I-09.png", "w": 1058, "h": 382}], "szoveg": "9. Három egyforma, pozitív töltésű, könnyű, de nem súlytalan bodzabélgolyó egy rögzített, mindkét végén zárt csőben függőleges irányba tud elmozdulni. A golyók nyugalomban, egyensúlyban vannak. Mit állíthatunk a golyók közötti h , illetve h távolságokról, ha a golyókon 1 2 lévő töltés mennyisége azonos, és a felső golyó nyomja a zárt cső tetejét? (A cső fala és a golyók között a súrlódás és az elektromos kölcsönhatás elhanyagolható.) A) h < h 1 2 B) h = h 1 2 C) h > h 1 2", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 10, "kepek": [{"src": "assets/exams/2025okt/I-10.png", "w": 1058, "h": 197}], "szoveg": "10. Az elektromágneses spektrum melyik tartományában található az ultrahang? A) A röntgensugárzás tartományában. B) Az ultraibolya tartományban. C) A mikrohullámok tartományában. D) Egyik fenti válasz sem helyes.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 11, "kepek": [{"src": "assets/exams/2025okt/I-11.png", "w": 1058, "h": 251}], "szoveg": "11. Kétféle, különböző, nagy felezési idejű radioaktív izotópot tartalmazó port keverünk össze. Az első por tömege m, aktivitása A , a második tömege 2m, aktivitása A . Mit 1 2 állíthatunk a keverék A aktivitásáról? A) A = A + A 1 2 B) A = A + 2ꞏA 1 2 C) A = (A + 2ꞏA )/3 1 2 D) Az adatok alapján nem tudjuk eldönteni, hogy mennyi a keverék aktivitása.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 12, "kepek": [{"src": "assets/exams/2025okt/I-12.png", "w": 1058, "h": 537}], "szoveg": "12. A Vénusz bolygónak a Holdhoz hasonlóan fázisai vannak, amit már Galilei is felfedezett. Így beszélhetünk újvénuszról, félvénuszról és telivénuszról is. A Vénusz távolsága a Naptól nagyjából 2/3 része a Nap-Föld távolságnak. Hozzávetőlegesen hányszor nagyobbnak látjuk a sarló alakú újvénusz külső körének átmérőjét, mint a telivénuszt? A) Körülbelül háromszor. B) Körülbelül négyszer. C) Körülbelül ötször. D) Körülbelül hatszor.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 13, "kepek": [{"src": "assets/exams/2025okt/I-13.png", "w": 1058, "h": 289}], "szoveg": "13. Az ábrán látható két huzal elektromos ellenállása azonos. A félkör alakú huzal vastagsága nagyobb, mint az egyenes huzalé. Melyiknek nagyobb a fajlagos ellenállása? A) A felsőnek. B) Az alsónak. C) Az információk alapján nem dönthető el.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 14, "kepek": [{"src": "assets/exams/2025okt/I-14.png", "w": 1058, "h": 360}], "szoveg": "14. Egy olyan csillag, melynek tömege a Naphoz hasonló nagyságú, a benne lévő hidrogén nagy részét már héliummá alakította a fúziós reakciók során. Mi a csillag fejlődésének következő állomása? A) Mivel az energiatermelése megszűnik, kihűl és szilárd bolygó lesz belőle. B) A gravitáció a csillag külső rétegeit a mag belsejébe húzza, majd olyan fúziós reakciók kezdenek energiát termelni, amelyben hélium alakul nehezebb atommagokká. C) A gravitáció a csillag külső rétegeit a mag belsejébe húzza, majd a csillag szupernovaként felrobban, és szétszórja a héliumgázt az univerzumban. D) A gravitáció a csillag külső rétegeit a mag belsejébe húzza, majd a csillag fekete lyukká omlik össze.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 15, "kepek": [{"src": "assets/exams/2025okt/I-15.png", "w": 1058, "h": 431}], "szoveg": "15. Egy ideális rugóra erősített test függőleges egyenes mentén rezgőmozgást végez. Gyorsulásának nagysága egy adott időpillanatban pontosan g. Mit állíthatunk erről a pillanatról? A) A test éppen az egyensúlyi helyzetén halad keresztül. B) A rugó megnyúlása ebben a pillanatban biztosan nulla. C) Ez a helyzet csak a rezgőmozgás felső fordulópontján lehetséges. D) A rugó megnyúlása vagy nulla, vagy az egyensúlyi helyzethez tartozó megnyúlás duplája.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}], "II": {"bevezeto": [{"src": "assets/exams/2025okt/II-bevezeto.png", "w": 1058, "h": 151}], "temak": [{"nr": 1, "cim": "Fuvola és klarinét", "kepek": [{"src": "assets/exams/2025okt/II-1.png", "w": 1058, "h": 1178}], "szoveg": "1. Fuvola és klarinét A fuvola mindkét végén nyitott sípként modellezhető, míg a klarinétot az egyik végén zárt sípként kell modellezni. Bár az eszközök hossza hasonló, a klarinét sokkal mélyebb hangokat tud megszólaltatni, mint a fuvola. A fuvola fúvónyílása a síp egyik nyitott \"vége\". A fuvolán a különböző hangmagasságokat úgy képzik, hogy a hanglyukak nyitásával-zárásával a testben rezonáló levegőoszlop hosszúságát módosítják, ami a fuvola – akusztikailag mindkét végén nyitottnak tekinthető – csöve esetén mindig nagyjából a megszólaló hang hullámhosszának fele. Átfúvással, tehát a megfúvás módjának megváltoztatásával a rezgő levegőoszlopot másféle, egy vagy két oktávval magasabb hangnak megfelelő rezgési módok felvételére lehet késztetni, ezzel tovább bővítve a hangkészletet. A fuvolán összesen három oktáv hangterjedelem érhető így el. A klarinét kvintelő hangszer. Ez azt jelenti, hogy hangspektruma túlnyomórészt a páratlan rendszámú felhangokat tartalmazza. Ennek nemcsak a hangszín szempontjából van jelentősége, hanem abban is, hogy átfúváskor is ennyivel lesz magasabb a hangja. A klarinét hangterjedelme az összes fúvós hangszer között a legnagyobb, közel négy oktáv, legmélyebb hangja: e, legmagasabb hangja: c&apos;&apos;&apos;&apos;. a) Mutassa be az egyik végén zárt, illetve mindkét végén nyitott sípokban kialakuló állóhullámok lehetséges hullámhosszait! Készítsen magyarázó ábrát! b) Milyen fizikai háttere van az általunk észlelt hangmagasságnak, hangerőnek, illetve hangszínnek? c) A három csőrészből összeállított fuvolát a fúvóka csövének kijjebb, illetve beljebb tolásával lehet hangolni. Miért? d) Adjon magyarázatot arra, miért tudjuk hallás segítségével megkülönböztetni a fuvola és a klarinét hangját még akkor is, ha azonos magasságú hangokat keltenek! e) Ha az alaphangon szóló fuvolába vagy klarinétba erősen fújunk, akkor megszólal az első felharmonikus (felhang) is. Hányszoros frekvenciával szól az első felharmonikus a fuvola, illetve a klarinét esetében? f) A leggyakoribb c-fuvola hossza 65 cm. Mekkora frekvenciájú az alaphangja? A hang terjedési sebessége 340 m/s. g) A fúvós hangszerek elhangolódnak, ha változik a levegő hőmérséklete. Mi ennek az oka?", "utmutato": [{"src": "assets/exams/2025okt/II-1-ut-1.png", "w": 1058, "h": 1358}, {"src": "assets/exams/2025okt/II-1-ut-2.png", "w": 1058, "h": 239}]}, {"nr": 2, "cim": "A keringési magasság csökkenése", "kepek": [{"src": "assets/exams/2025okt/II-2.png", "w": 1058, "h": 1441}], "szoveg": "2. A keringési magasság csökkenése Két, az űrben egymás körül a kölcsönös tömegvonzás hatására keringő test között a távolság lassan, de folyamatosan csökken. A magasság csökkenését különböző energiaelnyelő folyamatok okozhatják, és végül a keringés megszűnéséhez, a két test összeütközéséhez vezetnek. Nagy tömegű testek (pl. fekete lyukak, neutroncsillagok) esetén a gravitációs hatások is jelentős energiaveszteséget okoznak, például gravitációs hullámok formájában. Bolygók körül keringő testek esetén leginkább a légköri súrlódás, illetve elektromágneses hatások felelősek az energiaveszteségért. A Föld körül, alacsony pályamagasságon keringő testek esetében a légköri súrlódás az energiaveszteség fő oka. Mivel a földi légkör sűrűsége még 100 – 500 km magasságban is számottevő, a nagy sebességgel haladó testek a légkör részecskéivel ütközve veszítenek mozgási energiájukból, és ezzel egyidejűleg jelentősen fel is forrósodnak. Emiatt a Föld körül kb. 400 km magasan keringő ISS (Nemzetközi Űrállomás) havonta körülbelül 2 km-el kerül közelebb a Földhöz, ezt a magasságcsökkenést időnként rakétahajtóművek bekapcsolásával kell korrigálni. A legkisebb pályamagasság, amelyen egy Föld körül körpályán keringő test legalább egy teljes körbefordulást még meg tud tenni meghajtás nélkül, körülbelül 150 km. Ezalatt a magasság alatt egy test már egyre rohamosabban fékeződik az egyre sűrűbb légkör miatt, így vagy lezuhan, vagy (kisebb testek esetén) a légköri súrlódás hatására elég. a) Írja fel az általános tömegvonzás törvényét, magyarázza el a benne szereplő fizikai mennyiségek jelentését! b) Milyen törvényszerűségek ismertek a Nap körül keringő bolygók mozgására vonatkozóan? c) Hogyan változik (csökken vagy növekszik) a Föld felett adott sebességgel haladó testre ható légköri súrlódási erő nagysága a felszín feletti magasság csökkenésekor? Mi a magasságfüggés oka? d) Hogyan változik (csökken vagy növekszik) a Föld felett adott magasságban haladó testre ható légköri súrlódási erő nagysága, ha a test sebessége növekszik? e) Hogyan függ a Föld felett körpályán keringő test sebessége a keringés magasságától? Írjon fel egy olyan egyenletet, amiből kifejezhető a sebesség magasságfüggése! f) Vajon a Nemzetközi Űrállomás, vagy pedig a felszín felett kb. 36 000 km geostacionárius pályán keringő műholdak pályamagasság-csökkenése jelentősebb? Válaszát indokolja! g) Milyen hatása van a légköri súrlódásnak a pályamagasság-csökkenésen kívül? Milyen összefüggésben van ez a hullócsillagok jelenségével? h) Mekkora egy 620 km magasban körpályán keringő műhold keringési sebessége? (A Föld tömege M = 6ꞏ10 24 kg, a Föld sugara R = 6380 km, γ = 6,67ꞏ10 -11 Nꞏm 2 ꞏkg -2 )", "utmutato": [{"src": "assets/exams/2025okt/II-2-ut-1.png", "w": 1058, "h": 1184}, {"src": "assets/exams/2025okt/II-2-ut-2.png", "w": 1058, "h": 758}]}, {"nr": 3, "cim": "A fény törése és a látás", "kepek": [{"src": "assets/exams/2025okt/II-3.png", "w": 1058, "h": 1441}], "szoveg": "3. A fény törése és a látás „A Nap sugári a szem gombján általütvén, a szem-fényen meghajulván, béviszik a szem tövére a dolog képét, de noha a kép visszálosan irattatik ott le, a szem holott visszaerőlködik, a lélek a visszaerőlködés lineája szerént nyomozván, az észrevett látattra, amit lát, igaz állapota szerént láttya és nem visszáloson.” Molnár János: A természetiekről Nevvton tanítványinak nyomdoka szerént … Posonyban és Kassán 1777 Robert Hooke mikroszkópja (1667) a) Ismertesse a fény törésének törvényét! b) Mutassa be a vékony lencsék képalkotását leíró leképezési törvényt, ismertesse és értelmezze a törvényben szereplő mennyiségeket! c) Hogyan adható meg a nagyítás? Mit állíthatunk a nagyítás abszolút értékéről kicsinyítés esetén? d) Értelmezze a dioptria fogalmát egy vékony lencse esetében, határozza meg, milyen tényezőktől függ egy vékony lencse dioptriája? e) Milyen lencsék dioptriája pozitív, és milyeneké negatív? Vázlatos rajzon mutassa be, hogyan törik meg a fényt a pozitív, illetve negatív dioptriájú lencsék, ha párhuzamos fénynyalábbal világítjuk meg őket! f) Mit jelent és miből fakad a vékony lencsék színhibája? g) Mit nevezünk rövidlátásnak, illetve távollátásnak? Írja le ezek korrigálásának módját a megfelelő lencsék megnevezésével és dioptriájuk előjelének megadásával!", "utmutato": [{"src": "assets/exams/2025okt/II-3-ut-1.png", "w": 1058, "h": 631}, {"src": "assets/exams/2025okt/II-3-ut-2.png", "w": 1058, "h": 1481}]}], "kifejtes": [{"src": "assets/exams/2025okt/II-kifejtes.png", "w": 1058, "h": 1442}]}, "III": [{"nr": 1, "kepek": [{"src": "assets/exams/2025okt/III-1.png", "w": 1058, "h": 1219}], "szoveg": "1. Egy rugós játékpuska rugóját 12 cm-el kell összenyomni, hogy kilövésre kész állapotba kerüljön. Ha a felhúzott játékpuskából egy 4 g tömegű lövedéket függőlegesen felfelé kilövünk, az 10 m magasra emelkedik az összenyomott rugó tetejétől számítva. Ez a lövedék kicsi, nem szorul a cső falához, ezért a puska csövében a súrlódása elhanyagolható. Ezután a puskát ismét felhúzzuk, majd 1,5 m magasan a vízszintes talaj felett, a csövet vízszintesen tartva egy 6 g tömegű lövedéket lövünk ki belőle, amely 5 m távolságban ér földet. Ez a lövedék kissé nagyobb, mint az előző, így a csőben már nem hanyagolható el a súrlódás. a) Mekkora a puska rugójának rugóállandója? b) Mekkora a súrlódási erő a puska csöve és a vízszintesen kilőtt lövedék között, ha a lövedék 0,5 m utat tesz meg a csőben? (g = 9,8 m/s 2 , légellenállás elhanyagolható.)", "pont": 13, "reszek": [{"betu": "a", "pont": 5}, {"betu": "b", "pont": 8}], "megoldas": [{"src": "assets/exams/2025okt/III-1-ut.png", "w": 1058, "h": 1213}]}, {"nr": 2, "kepek": [{"src": "assets/exams/2025okt/III-2.png", "w": 1058, "h": 203}], "szoveg": "2. Egy karácsonyfát díszítő lámpasor 20 kis égőből áll, melyeket sorosan kapcsolnak. a) Mekkora az egyes izzók ellenállása, ha rajtuk a 12 V, 2,2 W felirat olvasható? b) Ha a lámpasort 230 V feszültségre kapcsoljuk, mennyi áram folyik át az égőkön? c) Amikor az egyik égő kiég, szeretnénk kicserélni, de csak 24 V; 2,2 W, illetve 6 V; 2,2 W feliratú lámpáink vannak. Melyik égőt tegyük a kiégett helyére? Leadja-e a pótizzó a névleges teljesítményét? Válaszát számítással is indokolja!", "pont": 13, "reszek": [{"betu": "a", "pont": 3}, {"betu": "b", "pont": 2}, {"betu": "c", "pont": 8}], "megoldas": [{"src": "assets/exams/2025okt/III-2-ut.png", "w": 1058, "h": 1455}]}, {"nr": 3, "kepek": [{"src": "assets/exams/2025okt/III-3.png", "w": 1058, "h": 241}], "szoveg": "3. Egy üzemben a hegesztési varratok átvilágítására 60 Co-izotóp -sugárzását használják. A 60 Co bomlásakor atommagonként két -foton keletkezik. Az egyik foton energiája 1,17 MeV, a másiké 1,33 MeV. A radioaktív preparátum a beszerzéskor 3,7ꞏl0 10 Bq aktivitású volt, egy év alatt aktivitása 12,2%-kal csökkent. a) Mennyi a felezési idő? b) Mekkora volt a preparátumból egy másodperc alatt kilépő -fotonok összenergiája joule-ban mérve a beszerzéskor?", "pont": 10, "reszek": [{"betu": "a", "pont": 6}, {"betu": "b", "pont": 4}], "megoldas": [{"src": "assets/exams/2025okt/III-3-ut.png", "w": 1058, "h": 1436}]}, {"nr": 4, "kepek": [{"src": "assets/exams/2025okt/III-4.png", "w": 1058, "h": 207}], "szoveg": "4. Egy optikai padon mozgatható vékony gyűjtőlencse egy, a lencse mögött 1 méterre elhelyezkedő rögzített ernyőn készít éles képet egy olyan tárgyról, ami a lencsétől 3 méterre helyezkedik el. a) Mekkora a lencse fókusztávolsága? b) Mennyivel és merre kell elmozdítani a lencsét, hogy az éles képet hozzon létre az ernyőn, ha a tárgyat 1 méterrel elmozdítjuk az ernyő felé?", "pont": 11, "reszek": [{"betu": "a", "pont": 3}, {"betu": "b", "pont": 8}], "megoldas": [{"src": "assets/exams/2025okt/III-4-ut.png", "w": 1058, "h": 842}]}]}, {"id": "2025maj", "cim": "2025. május", "datum": "2025. május 20.", "ido": 240, "kod": null, "forras": "Oktatási Hivatal – emelt szintű fizika írásbeli feladatlap és javítási-értékelési útmutató", "I": [{"nr": 1, "kepek": [{"src": "assets/exams/2025maj/I-01.png", "w": 1058, "h": 250}], "szoveg": "1. Két diák egy-egy gördeszkán áll, mindketten nyugalomban vannak. Kezükben egy őket összekötő kötél végeit tartják. Egy adott pillanatban húzni kezdik egymást a kötél segítségével. A gördeszkák súrlódása elhanyagolható. A húzás hatására a diákok egymás felé gurulnak. Melyikük mozdul el kevesebbet? A) Mindenképpen az, aki erősebben húz. B) Mindenképpen az, aki nagyobb tömegű. C) Mindenképpen egyforma a két diák elmozdulása.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 2, "kepek": [{"src": "assets/exams/2025maj/I-02.png", "w": 1058, "h": 221}], "szoveg": "2. Egy vastag fába egy lövedék 1 cm mélyre fúródik be. Milyen mélyen fúródna be a lövedék a fába, ha az kétszeres sebességgel érkezik a fához, és a fa anyaga által a lövedékre kifejtett fékezőerő nem változik a fékeződés során? A) 2 cm B) 3 cm C) 4 cm", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "C"}, {"nr": 3, "kepek": [{"src": "assets/exams/2025maj/I-03.png", "w": 1058, "h": 221}], "szoveg": "3. Váltóáramú körbe kondenzátort kapcsolunk. Mekkora a kondenzátor elektromos energiája abban a pillanatban, amikor az áramerősség nulla? A) A kondenzátor energiája ebben a pillanatban nulla. B) A kondenzátor energiája ebben a pillanatban maximális. C) A kondenzátor energiája ebben a pillanatban a maximális érték négyzetgyök ketted része.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 4, "kepek": [{"src": "assets/exams/2025maj/I-04.png", "w": 1058, "h": 387}], "szoveg": "4. Egy G súlyú ládát az ábrán látható elrendezés tart egyensúlyban. A csigát tartó kötél 45°-os szöget zár be a mennyezettel. A kötelek és a csiga súlytalannak tekinthetők. Mekkora erő hat az A pontban a falra, illetve a B pontban a mennyezetre? A) Mindkét pontban G-nél nagyobb erő hat. B) Az A pontban G, a B pontban G-nél nagyobb erő hat. C) Az A pontban G, a B pontban G-nél kisebb erő hat. D) Mindkét pontban G erő hat.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 5, "kepek": [{"src": "assets/exams/2025maj/I-05.png", "w": 1058, "h": 250}], "szoveg": "5. Egy tartályban azonos tömegű hélium- és argongáz keveréke található 20 C hőmérsékleten. Melyik állítás helyes? A) A héliumatomok átlagos sebessége megegyezik az argonatomokéval. B) A tartályban a hélium- és az argonatomok száma azonos. C) A két gáz parciális nyomása – azaz külön-külön az egyik, illetve a másik gáz nyomása az edényben – egyenlő. D) Az előző állítások egyike sem igaz.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 6, "kepek": [{"src": "assets/exams/2025maj/I-06.png", "w": 1058, "h": 289}], "szoveg": "6. Az alábbi elrendezésben a tekercs áramkörét a kapcsolóval (K) zárjuk. Milyen irányú áram jön létre az R ellenálláson? A) a-ból b-be irányuló áramlökés. B) b-ből a-ba irányuló áramlökés. C) Nem jön létre áramlökés.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 7, "kepek": [{"src": "assets/exams/2025maj/I-07.png", "w": 1058, "h": 434}], "szoveg": "7. Egy ejtőernyős kiugrik egy vízszintesen haladó repülőgépből, majd egy percnyi zuhanás után kinyitja az ejtőernyőt. A sebesség függőleges komponensének nagyságát a mozgás során a mellékelt grafikon mutatja. A mozgásra vonatkozó alábbi állítások közül melyik a helyes? A) Az ejtőernyős az t időpillanatban nyitja ki az ejtőernyőt, ezt követően nem A gyorsul tovább. B) Az ejtőernyős a t időpillanatban nyitja ki az ejtőernyőt, ezt követően a B sebessége gyorsan csökkeni kezd. C) Az ejtőernyős a t időpillanatban földet ér. C", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 8, "kepek": [{"src": "assets/exams/2025maj/I-08.png", "w": 1058, "h": 283}], "szoveg": "8. Egy adott fémet 1,4 eV energiájú fotonokat tartalmazó monokromatikus fény világít meg. Ennek hatására a fémből elektronok lépnek ki. A kilépő elektronok maximális mozgási energiája 0,3 eV lesz. Mekkora lesz a kilépő elektronok maximális energiája, ha 2,1 eV energiájú fotonokat tartalmazó fénnyel világítjuk meg a fémet? A) Kb. 0,3 eV. B) Kb. 0,6 eV. C) Kb. 1 eV. D) A fémből ekkor nem lépnek ki elektronok.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 9, "kepek": [{"src": "assets/exams/2025maj/I-09.png", "w": 1058, "h": 338}], "szoveg": "9. Egy kör alakú lencséket befogadó keretbe az olvasószemüveget készítő optikus fordítva szerelte be a lencséket. Így a domború oldalukkal most befelé állnak a szem felé (ld. ábra). Hogyan használható most a szemüveg? A) A szemüveg most is olvasószemüvegként használható. B) A szemüveg most már rövidlátást korrigál. C) A szemüveg így egyáltalán nem használható látásjavításra.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 10, "kepek": [{"src": "assets/exams/2025maj/I-10.png", "w": 1058, "h": 283}], "szoveg": "10. Egy merev rúdra szerelt golyót függőleges síkban, egyenletesen forgatunk az ábrának megfelelően. Mely helyzetekben lesz a golyó gyorsulásának abszolút értéke azonos? A) Az 1. és a 3. helyzetben. B) A 2. és a 4. helyzetben. C) A gyorsulás nagysága mind a négy helyzetben azonos. D) A gyorsulás nagysága mind a négy helyzetben különböző .", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 11, "kepek": [{"src": "assets/exams/2025maj/I-11.png", "w": 1058, "h": 276}], "szoveg": "11. Egy tiszta éjszakán teleholdat látunk az égen. Milyen földfázist lát ekkor egy, a Holdon álló űrhajós, ha feltekint az égre? A) ,,Újföldet”. B) ,,Teleföldet”. C) A kérdésnek nincs értelme, hiszen a Hold keringése során mindig ugyanazt az oldalát mutatja a Föld felé. D) Ennyi információból nem lehet eldönteni, mert a Föld naponta megfordul a tengelye körül.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 12, "kepek": [{"src": "assets/exams/2025maj/I-12.png", "w": 1058, "h": 335}], "szoveg": "12. Egy tengerszinten lévő kútból vizet szeretnénk felszívni egy talajon álló szivattyúval. Ha a szivattyú csövét leengedjük a kútba, elvileg legfeljebb 10 m mélyről, a veszteségek miatt a gyakorlatban csak 7–8 m mélyről hozható fel a víz. Milyen mélyről tudná ugyanez a szivattyú felszivattyúzni a vizet egy 3000 m magas fennsíkon lévő kútból? A) Kisebb mélységből, mert a magas fennsíkon kisebb a légnyomás. B) Valamivel nagyobb mélységből, mert a magas fennsíkon kissé kisebb a gravitációs állandó, így a víz súlya is csökken egy kicsit. C) A magas fennsíkon is ugyanolyan mélyről tudná felszivattyúzni, mert ez az adat csak a motor teljesítményétől függ.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 13, "kepek": [{"src": "assets/exams/2025maj/I-13.png", "w": 1058, "h": 432}], "szoveg": "13. Két rézhuzal tömege és hőmérséklete megegyezik, azonban az A huzal hossza ötszöröse a B huzal hosszának. Mekkora a két huzal elektromos ellenállásának aránya? A) R A  25 R B B) R A  5 R B C) R 1 A  R 5 B D) R 1 A  R 25 B", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}, {"nr": 14, "kepek": [{"src": "assets/exams/2025maj/I-14.png", "w": 1058, "h": 532}], "szoveg": "14. Egy rugalmas gumiszálon két jel terjed egymás felé az ábrán látható módon. Az alábbi ábrák közül melyik mutatja helyesen a gumiszál alakját egy későbbi időpillanatban? A) Az A) ábra. B) A B) ábra. C) A C) ábra.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 15, "kepek": [{"src": "assets/exams/2025maj/I-15.png", "w": 1058, "h": 322}], "szoveg": "15. A pozitron az elektron antirészecskéje, tehát a két részecske tömege és töltésének nagysága is megegyezik, azonban elektromos töltésük ellenkező előjelű. Tegyük fel, hogy az A tömegszámú és Z rendszámú izotóp pozitív béta bomló, vagyis radioaktív bomlásakor pozitront bocsát ki. Mekkora lesz a bomlás után létrejövő izotóp tömegszáma és rendszáma? A) A, (Z – 1) B) A, (Z + 1) C) (A – 1), Z D) (A + 1), Z", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "A"}], "II": {"bevezeto": [{"src": "assets/exams/2025maj/II-bevezeto.png", "w": 1058, "h": 151}], "temak": [{"nr": 1, "cim": "Infravörös fény és a szem", "kepek": [{"src": "assets/exams/2025maj/II-1.png", "w": 1058, "h": 1178}], "szoveg": "1. Infravörös fény és a szem Egy nemrég megjelent tanulmány szerint az emberi szem képes érzékelni a szemnek amúgy láthatatlan infravörös fényt. A kutatás azután kezdődött, hogy több tudós is zöld fényvillanásokat vélt látni, miközben infravörös lézerekkel dolgozott. A szakemberek tudni akarták, hogyan érzékelhették azt a fényt, hiszen ez elvileg lehetetlen. A kutatócsoport egyik vezetője, Frans Vinberg beszámolója szerint különböző időtartamú lézerimpulzusokkal kísérleteztek, melyek rendre ugyanannyi fotont bocsátottak ki. Az eredmények szerint minél rövidebb az impulzus, annál nagyobb a valószínűsége, hogy az emberi szem érzékeli. A fotonokat úgy érzékeli a szem, hogy a retinában lévő fotopigment nevű molekulák fotonokat nyelnek el, és ennek hatására azok aktiválódnak. Az aktiválódás vegyi reakciót vált ki a retinában. Jellemzően minden egyes fotopigment egy-egy fotont nyel el. Ha túl kicsi a foton energiája, akkor nem aktiválódik a fotopigment-molekula, így nincs észlelés. Amikor azonban sok fotont adagoltak a rövid impulzusú, gyorsan pulzáló lézerfénybe, akkor egyetlen fotopigment egyszerre akár két fotont is elnyelt. A jelenséget kétfotonos abszorpciónak nevezik. A tanulmány szerint két, egyidejűleg befogott foton energiája már elég lehet a fotopigment aktiválásához, és így az amúgy láthatatlan infravörös fény észleléséhez. A jelenség bekövetkeztére példa lehet egy olyan 1  J (10 - 6 J) energiájú, 100 femtoszekundumos (10 -13 s) impulzushosszú lézer, mely 1000 nm-es (10 -6 m) infravörös fotonokat bocsát ki. Az impulzushossz azt az időt jelöli, ameddig a fotonkibocsátás zajlik, az impulzus energiáján az impulzushoz tartozó összes foton együttes energiáját értjük. a) Mi a foton? Hogyan függ a foton energiája a fény hullámhosszától? b) Vázlatosan ismertessen egy-egy, a fény hullámtermészetét és részecsketermészetét igazoló kísérletet! c) Nagyjából mely hullámhossztartományban érzékeli az emberi szem a fényt? Mekkora frekvenciatartománynak felel meg ez? d) Mekkora annak az egyetlen fotonnak a hullámhossza, ami két, 1000 nm hullámhosszúságú foton együttes energiáját tartalmazza? Milyen színű ez a fény? e) Magyarázza meg, miért érzékeltek zöld villanásokat az infravörös fénnyel dolgozó tudósok! f) Mekkora a jelenség bekövetkeztére példaként megadott lézerimpulzus teljesítménye?", "utmutato": [{"src": "assets/exams/2025maj/II-1-ut.png", "w": 1058, "h": 1308}]}, {"nr": 2, "cim": "GPS-rendszer", "kepek": [{"src": "assets/exams/2025maj/II-2.png", "w": 1058, "h": 1436}], "szoveg": "2. GPS-rendszer A GPS egy modern helymeghatározó rendszer, amellyel háromdimenziós helyzetmeghatározás végezhető a földfelszínen, vízfelszínen vagy levegőben. Pontossága jellemzően méteres nagyságrendű, de különleges mérési módszerekkel, fix földi bázisállomás jelét is felhasználva akár milliméteres pontosságot is el lehet érni, valós időben. A GPS-t sok más technológiához hasonlóan katonai célokra fejlesztették ki, de ma már a civil élet számos területén széles körben alkalmazzák. Az alaprendszer a következő elemekből áll: - 24 darab, 12 órás keringési idejű, körpályákon keringő műhold, amelyek pályasíkjai egymással 30°-os szöget zárnak be. Mindegyik műholdon 2 atomóra található. - 5 darab földi, ún. monitorállomás, ahonnan az atomórák pontatlanságait korrigálják. - GPS-vevőberendezés, amelyből a Föld bármely pontján számtalan lehet. A GPS-műholdak két mikrohullámú frekvencián (1575,42 MHz és 1227,6 MHz) sugároznak. Egy adott pontban a helymeghatározást akkor tudjuk pontosan elvégezni, ha ismerjük a műholdak pontos helyét, és azt az időt, ami alatt a jel a műholdtól a készülékig eljutott. Mivel ismerjük a rádióhullámok terjedési sebességét, és ismerjük a rádióhullám kibocsátásának és beérkezésének idejét, így ezek alapján meghatározhatjuk a forrás távolságát. A Föld felszínén három ismert helyzetű ponttól mért távolság pontos ismeretében már meg tudjuk határozni a pozíciót. A többi műholdtól mért távolságokkal pontosítani tudjuk ezt az értéket. a) Mutassa be Kepler II. és III. törvényét a Föld körül keringő műholdak esetében! Melyik Kepler törvényből és hogyan következik, hogy a körpályán keringő GPS-műholdak sebessége állandó nagyságú? b) A GPS-műholdak közül egy körpályán több is kering. Lehetséges-e, hogy az egyik utolérje a másikat, és összeütközzenek? Válaszát indokolja! c) A Földhöz közel és a Földtől távol egyaránt keringenek körpályákon mesterséges holdak. Hogyan függ a Föld felszínétől vett távolságtól ezen mesterséges holdak keringési ideje? Válaszát indokolja! A 92 perces keringési idejű Nemzetközi Űrállomás vagy a GPS-műholdak keringenek magasabban? d) Mit állíthatunk a Földhöz közelebbi, illetve a Földtől távolabbi körpályán keringő mesterséges holdak sebességének viszonyáról? Válaszát indokolja! Hasonlítsa össze a Nemzetközi Űrállomás és egy GPS-műhold sebességét! Melyik nagyobb? e) Mit nevezünk geostacionárius műholdnak? Adja meg, hogy a Földfelszín mely jellegzetes pontjainak környezetében lesz biztosan nem látható egy geostacionárius pályára állított műhold! f) Miért nem lehet olyan, az egész Földgolyón használható GPS-rendszert kifejleszteni, ami kizárólag geostacionárius műholdakat használ? g) Ha a műhold rádiójelének idejét egymilliárdod másodperc pontossággal tudjuk mérni, milyen pontossággal tudjuk a műhold távolságát meghatározni?", "utmutato": [{"src": "assets/exams/2025maj/II-2-ut.png", "w": 1058, "h": 1470}]}, {"nr": 3, "cim": "A hő terjedése", "kepek": [{"src": "assets/exams/2025maj/II-3.png", "w": 1058, "h": 1441}], "szoveg": "3. A hő terjedése „A tűz és a meleg minden testekbe béhat. Ha a házat béfűtik, minden benne megmelegszik. De a vastag testek egyszerre több tűzrészecskét vehetnek és tovább is tarthatják azokat magokba, mint a vékony testek, ugyanezért lehet példának okáért az értznemeket és a köveket keményebben megmelegíteni, mint a fát.” Szőke Ferenc: A’tudományok’ rövid summája – részlet, Pozsony, 1806 A hő terjedésének három formája a hővezetés, hőáramlás és hősugárzás. a) Mutasson be egy gyakorlati példát a hővezetésre! Milyen anyagszerkezeti modell segítségével írható le a hővezetés nem-fémes anyagokban? b) Miért jó hőszigetelő a vattával bélelt dzseki, és miért nem az a hasonló borítású, béleletlen esőkabát? c) Mit nevezünk hőáramlásnak? Mutasson be egy gyakorlati példát egy a háztartásban zajló természetes (nem gépek által létrehozott) hőáramlásra! d) Ismertessen egy olyan időjárási jelenséget, mely a hőáramlással kapcsolatos! e) Mutasson be egy gyakorlati példát a hősugárzásra! Milyen típusú sugárzás a hősugárzás? Milyen közvetítő közegre van szükség a hősugarak terjedéséhez? f) Nevezzen meg egy, a hősugarakhoz hasonló sugárzást! Milyen fizikai jellemzőik egyeznek meg, és melyek különböznek? g) Ismertessen egy olyan gyakorlati jelenséget, melyben a hőterjedés több formája is szerepet játszik!", "utmutato": [{"src": "assets/exams/2025maj/II-3-ut.png", "w": 1058, "h": 1436}]}], "kifejtes": [{"src": "assets/exams/2025maj/II-kifejtes.png", "w": 1058, "h": 1412}]}, "III": [{"nr": 1, "kepek": [{"src": "assets/exams/2025maj/III-1.png", "w": 1058, "h": 1222}], "szoveg": "1. Egy l = 30 cm hosszú, könnyű, szigetelőfonál végén m = 1 g tömegű, kicsiny test helyezkedik el, melynek elektromos töltése Q = 10 -6 C. A fonál másik végét rögzítve a testet vízszintes irányú, homogén elektromos mezőbe helyezzük. Ennek hatására a fonál olyan egyensúlyi helyzetet vesz fel, amelyben a függőlegessel  = 20-os szöget zár be. a) Mekkora az elektromos térerősség nagysága? A fonalat a kis testtel függőleges helyzetbe állítjuk és ott a rendszert magára hagyjuk. b) Mekkora munkát végez az elektromos tér, illetve a gravitációs erő a testen, amíg a test visszaér az egyensúlyi helyzetébe? c) Mekkora sebességgel éri el az egyensúlyi helyzetet a test? (g = 9,8 m/s 2 )", "pont": 12, "reszek": [{"betu": "a", "pont": 4}, {"betu": "b", "pont": 4}, {"betu": "c", "pont": 4}], "megoldas": [{"src": "assets/exams/2025maj/III-1-ut.png", "w": 1058, "h": 1263}]}, {"nr": 2, "kepek": [{"src": "assets/exams/2025maj/III-2.png", "w": 1058, "h": 205}], "szoveg": "2. Egy megfelelő fémből fotokatódot készítünk. Azt tapasztaljuk, hogy a katódot 500 nm hullámhosszúságú fénnyel megvilágítva kétszer akkora lesz a kilépő elektronok maximális mozgási energiája, mint amikor 750 nm hullámhosszúságú fénnyel világítjuk meg. Mekkora a fém kilépési munkája és határfrekvenciája? (c = 3ꞏ10 8 m/s, h = 6,63ꞏ10 -34 Js)", "pont": 10, "reszek": [], "megoldas": [{"src": "assets/exams/2025maj/III-2-ut.png", "w": 1058, "h": 1436}]}, {"nr": 3, "kepek": [{"src": "assets/exams/2025maj/III-3.png", "w": 1058, "h": 366}], "szoveg": "3. Egy szobában, ahol a hőmérséklet 22 C, a légnyomás pedig 10 5 Pa, egy léggömböt 0,6 g héliummal töltünk meg úgy, hogy benne a gáz nyomása 1,05  10 5 Pa legyen. a) Mekkora a léggömb térfogata, ha a benne lévő gáz hőmérséklete szintén 22 C, és a hélium moláris tömege 4 g/mol? b) Mekkora a levegő sűrűsége a szobában, ha a levegő átlagos moláris tömege 29 g/mol? c) Ha a léggömböt elengedjük, akkor az felemelkedik, és végül a mennyezethez nyomódik. Mekkora erővel szorul a léggömb a mennyezethez, ha a léggömb gumi anyagának tömege 2 g? (g = 9,8 m/s 2 , R = 8,31 J/(molK))", "pont": 12, "reszek": [{"betu": "a", "pont": 4}, {"betu": "b", "pont": 3}, {"betu": "c", "pont": 5}], "megoldas": [{"src": "assets/exams/2025maj/III-3-ut.png", "w": 1058, "h": 1470}]}, {"nr": 4, "kepek": [{"src": "assets/exams/2025maj/III-4.png", "w": 1058, "h": 445}], "szoveg": "4. Bizonyos mobiltelefonok menürendszerét szakszervízekben bővíteni tudják, így például be lehet állítani, hogy a készülék jelezze ki azt is, hogy az akkumulátorának mekkora a pillanatnyi árama, illetve mekkora az akkumulátor kivezetésein mérhető feszültség. Egy ilyen készülék 120 mA áramot és 3600 mV feszültséget jelez, amikor be van kapcsolva a kijelzőjének megvilágítása. Beszélgetés közben az áram 240 mA értékre nőtt, a feszültség pedig 3500 mV-ra csökkent. a) Mekkora a készülék akkumulátorának belső ellenállása? b) Mekkora az akkumulátor elektromotoros ereje? c) Készenléti üzemmódban ennek a mobilnak 12 mA az áramfelvétele. Mekkora feszültséget jelez a készülék készenléti üzemmódban, és másodpercenként mennyivel csökken ilyenkor az akkumulátor energiája? d) A telefon szervízkönyvében ez a felirat található az akkumulátorról: 4000 mAh. Mit jelent ez az adat? Hány napig működhet a telefon készenléti üzemmódban?", "pont": 13, "reszek": [{"betu": "a", "pont": 4}, {"betu": "b", "pont": 2}, {"betu": "c", "pont": 4}, {"betu": "d", "pont": 3}], "megoldas": [{"src": "assets/exams/2025maj/III-4-ut.png", "w": 1058, "h": 1470}]}]}, {"id": "2024maj", "cim": "2024. május", "datum": "2024. május 22.", "ido": 240, "kod": null, "forras": "Oktatási Hivatal – emelt szintű fizika írásbeli feladatlap és javítási-értékelési útmutató", "I": [{"nr": 1, "kepek": [{"src": "assets/exams/2024maj/I-01.png", "w": 1058, "h": 427}], "szoveg": "1. Egy toronyból 𝒗 kezdősebességgel vízszintesen elhajítunk egy 𝟎 testet. Mennyi idő múlva duplázódik meg a mozgási energiája, ha a légellenállástól eltekinthetünk? Válaszát egyértelműen jelölje, pl. bekarikázással! A) v 0 2 g B) v 0 g C) 2v 0 g D) A kérdés megválaszolásához több adatra van szükség.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 2, "kepek": [{"src": "assets/exams/2024maj/I-02.png", "w": 1058, "h": 362}], "szoveg": "2. Egy nyitott sípot (mindkét végén nyitott, vékony csövet) keresztben félbevágunk, majd az egyik oldalát lezárjuk, így fele olyan hosszú, zárt sípot hozunk létre. Hogyan viszonyul egymáshoz a kezdetben használt nyitott síp illetve a felezés és lezárás után létrejött zárt síp alaphangjának a hullámhossza? A) A zárt síp alaphangjának hullámhossza a nyitott síp alaphangjáénak negyede. B) A zárt síp alaphangjának hullámhossza a nyitott síp alaphangjáénak fele. C) A zárt síp alaphangjának hullámhossza a nyitott síp alaphangjáéval egyenlő. D) A zárt síp alaphangjának hullámhossza a nyitott síp alaphangjáénak kétszerese.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 3, "kepek": [{"src": "assets/exams/2024maj/I-03.png", "w": 1058, "h": 823}], "szoveg": "3. Egy teherautó tengelyének rugózását biztosító rendszer egy laprugóból és egy csavarrugóból van összeszerelve, amint a mellékelt ábra mutatja. Terheletlen állapotban a csavarrugó alsó vége nem ér hozzá a teherautó alvázához, attól y 0 távolságra van. A rugórendszer összenyomódását a terheletlen állapothoz képest y jelöli. Melyik grafikon mutatja helyesen a teherautóra helyezett teher G súlyát y függvényében? (A lemezrugó úgy viselkedik terhelés hatására, mint a csavarrugó.) A) Az A) grafikon. B) A B) grafikon. C) A C) grafikon. D) Csak a rugóállandók értékeinek ismeretében lehet eldönteni.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 4, "kepek": [{"src": "assets/exams/2024maj/I-04.png", "w": 1058, "h": 220}], "szoveg": "4. Lehetséges-e síkkondenzátor lemezei között mágneses teret létrehozni? A) Igen, például amikor a kondenzátor kisül, akkor a megváltozó elektromos tér mágneses teret indukál. B) A kondenzátorlemezek között csak elektromos tér jöhet létre, mivel a fémlemezek kiszorítják a mágneses teret a lemezek közül. C) Igen, de csak egy, a lemezek közé helyezett állandó mágnes segítségével.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 5, "kepek": [{"src": "assets/exams/2024maj/I-05.png", "w": 1058, "h": 260}], "szoveg": "5. Egy testet vízbe merítünk a Nemzetközi Űrállomáson a súlytalanság állapotában. Mit állíthatunk ebben az esetben a felhajtóerőről? A) A felhajtóerő nulla, mert súlytalanság állapotában nincs hidrosztatikai nyomás a folyadékokban. B) A felhajtóerő nulla, mert súlytalanság állapotában nincs gravitációs tér. C) A felhajtóerő a Földön és az űrállomáson ugyanakkora, hiszen a kiszorított víz mennyisége az űrállomáson ugyanakkora, mint a Földön.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 6, "kepek": [{"src": "assets/exams/2024maj/I-06.png", "w": 1058, "h": 675}], "szoveg": "6. Egy hosszú, vízszintes asztalon egy kiskocsi egyenes vonalú egyenletes mozgást végez. A kiskocsi platóján egy rugóhoz erősített, kis test harmonikusan rezeg a menetiránnyal párhuzamosan. Melyik görbe mutathatja helyesen a test x elmozdulását az asztalhoz képest az idő függvényében a rezgés során? A) Csak az A) görbe lehet helyes. B) Csak a C) görbe lehet helyes. C) A B) görbe vagy a C) görbe is lehet helyes. D) Az A) görbe vagy a B) görbe is lehet helyes.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 7, "kepek": [{"src": "assets/exams/2024maj/I-07.png", "w": 1058, "h": 404}], "szoveg": "7. Egy hegyi túrázásra szánt kerékpár gumiját felfújjuk a tenger szintjéhez közeli magasságon. A pumpa manométere a fújás végén 2,5 bar túlnyomást mutat. Ezután a kerékpárt kabinos felvonóval felvisszük 2500 m magasságba. Itt ismét ellenőrizzük a túlnyomást. Mit tapasztalunk? (Tegyük fel, hogy a gumi nem lyukas, és hogy a felvonó épületében a hőmérséklet ugyanaz lent, illetve fent, valamint a gumikerék térfogata állandó.) A) A túlnyomás változatlan, hiszen a bezárt levegő mennyisége, térfogata és hőmérséklete nem változott. B) A túlnyomás nő, mivel a légköri nyomás csökkent a magasban a tengerszinten lévő légnyomáshoz képest. C) A túlnyomás csökken, mivel a légköri nyomás csökkent a magasban a tengerszinten lévő légnyomáshoz képest.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 8, "kepek": [{"src": "assets/exams/2024maj/I-08.png", "w": 1058, "h": 329}], "szoveg": "8. Két pozitív, egyformán 2 C nagyságú ponttöltést kétféleképpen helyezünk el egy P ponttól 0,04 m távolságra a mellékelt két ábrának megfelelően. Melyik esetben lesz az elektromos térerősség a P pontban nulla? A) Csak az A) ábrának megfelelő elrendezésben. B) Csak a B) ábrának megfelelő elrendezésben. C) Mindkét elrendezésben nulla lesz P pontban a térerősség. D) Egyik elrendezésben sem lesz nulla P pontban a térerősség.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}, {"nr": 9, "kepek": [{"src": "assets/exams/2024maj/I-09.png", "w": 1058, "h": 248}], "szoveg": "9. Fókuszálhatja-e egy gyűjtőlencse egy prezentációkhoz használt lézermutató fényét? A) Igen, ilyenkor egy, a lencse után elhelyezett, körülbelül a fókusztávolsággal egyező távolságra lévő ernyőn a lézer fényfoltja sokkal kisebb és fényesebb lesz. B) Nem, mert a lézer fénye már eleve fókuszált. A lencse után helyezett ernyőn ugyanolyan fényfoltot látunk, mintha nem is volna ott a lencse. C) Nem, mert a lézer fénye koherens, ilyen fényt nem lehet fókuszálni.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 10, "kepek": [{"src": "assets/exams/2024maj/I-10.png", "w": 1058, "h": 318}], "szoveg": "10. A müonok a kozmikus sugárzás hatására a légkör tetején keletkeznek, és közel fénysebességgel érkeznek a Föld felszínére, ám a nyugvó müonok élettartama rövidebb, mint az általunk észlelt utazási idejük. Hogyan lehetséges ez? A) A speciális relativitáselmélet szerint az idő nem abszolút. B) Az általános relativitáselmélettel összhangban a Föld gravitációja elgörbíti a müonok pályáját, ezért hamarabb érnek a Föld felszínére. C) A müonok a keletkezésük után olyan nagy energiával rendelkeznek, hogy átlépik a fénysebességet, alagúteffektussal érnek hamarabb a Föld felszínére.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "A"}, {"nr": 11, "kepek": [{"src": "assets/exams/2024maj/I-11.png", "w": 1058, "h": 774}], "szoveg": "11. Arany János ezt írja a Toldi első énekében: „Azzal a nehéz fát könnyedén forgatja, Mint csekély botocskát, véginél ragadja; Hosszan, egyenesen tartja félkezével, Mutatván az utat, hol Budára tér el” A rúd tömegközéppontja a rúd közepén van. Hogyan tarthatta meg a rudat Toldi Miklós a végénél fogva? Melyik ábra mutatja helyesen a rúdra ható erőket? A) Az A) ábra. B) A B) ábra. C) A C) ábra. D) Egyik sem, nem lehet így megtartani a rudat, ez csak legenda.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "C"}, {"nr": 12, "kepek": [{"src": "assets/exams/2024maj/I-12.png", "w": 1058, "h": 203}], "szoveg": "12. Körülbelül mekkora lehet egy kritikus tömegű, dúsított urán 235-ös izotópjából készített gömb tömege? Ilyen volt az első atombomba. A) Körülbelül 5,6 gramm B) Körülbelül 56 kg C) Körülbelül 560 tonna", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 13, "kepek": [{"src": "assets/exams/2024maj/I-13.png", "w": 1058, "h": 298}], "szoveg": "13. Hogyan változna egy R sugarú homogén gömb felszínén a gravitációs gyorsulás értéke, ha a közepéből eltávolítanánk egy R/2 sugarú anyaggömböt? A) Nem változna. B) A felére csökkenne. C) A háromnegyed részére csökkenne. D) A hétnyolcad részére csökkenne.", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "D"}, {"nr": 14, "kepek": [{"src": "assets/exams/2024maj/I-14.png", "w": 1058, "h": 325}], "szoveg": "14. Két, félkör alakú drótból karikát készítünk. Az egyik félkör (ADB) ellenállása R, a másiké (ACB) 2R, ahogyan az ábra mutatja. Megmérjük az A és B, majd a C és D pontok között a karika ellenállását. Melyik lesz nagyobb? A) Az A és B pontok közötti ellenállás. B) A C és D pontok közötti ellenállás. C) A két ellenállás megegyezik egymással.", "betuk": ["A", "B", "C"], "pont": 2, "helyes": "B"}, {"nr": 15, "kepek": [{"src": "assets/exams/2024maj/I-15.png", "w": 1058, "h": 274}], "szoveg": "15. Egy magas épület tetejéről lökésmentesen elejtünk egy m tömegű testet. Mekkora lesz a még zuhanó test lendülete (impulzusa) nem túl hosszú t idő múlva, ha a légellenállástól eltekintünk? A)   m g t B) mꞏgꞏt C) ½ ꞏ mꞏgꞏt 2 D) mꞏgꞏt 2", "betuk": ["A", "B", "C", "D"], "pont": 2, "helyes": "B"}], "II": {"bevezeto": [{"src": "assets/exams/2024maj/II-bevezeto.png", "w": 1058, "h": 151}], "temak": [{"nr": 1, "cim": "Elektromos gépjárművek akkumulátorai", "kepek": [{"src": "assets/exams/2024maj/II-1.png", "w": 1058, "h": 1168}], "szoveg": "1. Elektromos gépjárművek akkumulátorai A modern, tisztán elektromos meghajtású autókban a közlekedéshez szükséges energiát szinte kivétel nélkül kb. 3,7 V feszültségű Li-ion cellákból összeállított modulok biztosítják (egy tipikus modul 96 sorba kötött cellából áll). Jelenleg ez a technológia képes leginkább megfelelni a különböző követelményeknek. Ezek közül kiemelkedik a nagy energiasűrűség, ami ahhoz szükséges, hogy észszerű súly mellett megfelelő hatótávolsággal rendelkezzenek a járművek. A Li-ion modulok ún. fajlagos energiája rendszerint 130 Wh/kg körül van, így a beépített, tipikusan 30–90 kWh kapacitású akkumulátorcsomagok súlya tekintélyes. Ezek már 200–500 km hatótávolságot tesznek lehetővé egy teljes töltéssel. A legmodernebb autók hatékonysága 150 Wh/km körül van. Természetesen a körülmények és a vezetési stílus rengeteget számítanak, a nagy sebesség vagy ismételt gyorsítás/fékezés az elektromos autóknál is nagyobb energiafogyasztást eredményez. Lényeges, hogy az akkumulátorok hirtelen nagy teljesítmény leadására legyenek képesek, azaz kis belső ellenállásúak legyenek. Értelemszerűen nagy jelentősége van az akkumulátorok hasznos élettartamának is. Az akkumulátorok hasznos kapacitása mind a használati idővel, mind pedig a feltöltés-lemerítés ciklusok számával fokozatosan csökken, ami a gépkocsi hatótávolságának csökkenését eredményezi. Ez azonban nagyban függ a használat módjától, mivel egy teljes feltöltés-lemerítés ciklus sokkal jobban igénybe veszi a cellákat, mint például egy félig lemerített állapotból 90%-os töltöttségig terjedő ciklus. Ezért a gyártók nem is engedik a „teljes kapacitást” kihasználni (azaz teljesen feltölteni, illetve lemeríteni az akkumulátorokat), ami lehetővé teszi, hogy tipikusan 8 év vagy 160 000 km garanciát adjanak az akkumulátorokra. a) Mit értünk egy akkumulátor elektromotoros erején, belső ellenállásán, illetve kapocsfeszültségén? b) Mit nevezünk rövidzárási áramnak? Hogyan függ az akkumulátor paramétereitől? c) Mit jelent egy kicsiny tölthető elem (akkumulátor) oldalán a 2500 mAh felirat? d) Magyarázza el, hogy miért lényeges, hogy kicsi legyen az akkumulátor belső ellenállása! e) Magyarázza el, hogy miért lehet egy teljesen feltöltött elektromos autóval lényegesen rövidebb távolságot megtenni állandó 130 km/h sebességgel, mint állandó 90 km/h sebességgel! f) Körülbelül mekkora egy akkumulátormodul feszültsége, ha 96 cella van benne sorba kapcsolva? g) Számítsa ki, hogy körülbelül mekkora távolságot tehet meg egy elektromos autó 1000 teljes feltöltés-lemerülés ciklus alatt, ha egy általánosnak tekinthető 50 kWh kapacitású akkumulátorcsomag van benne!", "utmutato": [{"src": "assets/exams/2024maj/II-1-ut-1.png", "w": 1058, "h": 1308}, {"src": "assets/exams/2024maj/II-1-ut-2.png", "w": 1058, "h": 446}]}, {"nr": 2, "cim": "A 3D-s szemüveg", "kepek": [{"src": "assets/exams/2024maj/II-2.png", "w": 1058, "h": 1441}], "szoveg": "2. A 3D-s szemüveg A térlátásunk azon alapszik, hogy a két szemünk nem egy helyen van, így az egyik szemünkkel egy kicsit más nézőpontból látjuk a világot, mint a másikkal. Az agyunk a két kissé különböző képből alakítja ki a térérzetünket. A síkba vetített képek ezt nem adják vissza, csak ha megoldjuk, hogy a két szemünk két különböző képet láthasson. A 3D mozikban régebben lineáris polárszűrőkkel oldották meg ezt a problémát. A vászonra két különböző nézőpontból felvett filmet vetítettek két, egymásra merőlegesen polarizált fénynyalábbal. Egy megfelelő szemüveggel nézve a vásznat, az egyik szemünk csak az egyik, a másik szemünk csak a másik filmet látta, mert a szemüveg lencséinek a helyén két polárszűrő volt. A módszert mára tovább tökéletesítették. 1. ábra 2. ábra a) Értelmezze a hullámokat leíró főbb mennyiségeket: amplitúdó, periódusidő, frekvencia, hullámhossz, terjedési sebesség! Milyen összefüggéseket állapíthatunk meg ezen mennyiségek között? b) Mit nevezünk transzverzális, illetve longitudinális hullámnak? Melyik hullám polarizálható? c) Mutassa be a polarizáció jelenségét! Adjon meg egy módot, amivel a polarizáció megvalósítható! d) Hogyan kell elhelyezni a polárszűrőket a szemüvegben ahhoz, hogy a megfelelő 3D-s élményben legyen részünk? e) Hogyan befolyásolja a látványt, ha valaki a szemüveget viselve pont 90°-kal az egyik válla irányában elbillenti a fejét? f) A 2. ábrán két, a feladatban leírt, egyforma szemüvegről készült fényképet láthatunk. Magyarázza meg, hogy miért látjuk a hátsó szemüveg, egyik „lencséjét” sötétnek, míg a másikat világosnak! Merre állnak az elülső szemüveg szárai, a hátsó szemüveggel megegyezően vagy ellentétesen?", "utmutato": [{"src": "assets/exams/2024maj/II-2-ut-1.png", "w": 1058, "h": 977}, {"src": "assets/exams/2024maj/II-2-ut-2.png", "w": 1058, "h": 567}]}, {"nr": 3, "cim": "A foton fogalma, a fotocella működése", "kepek": [{"src": "assets/exams/2024maj/II-3.png", "w": 1058, "h": 1436}], "szoveg": "3. A foton fogalma, a fotocella működése Hiábavaló kísérleteim, hogy a hatáskvantumot valamiképpen belehelyezzem a klasszikus elméletbe, több éven át elhúzódtak, és igen sok munkámba kerültek. Néhány kollégám valami tragikusat látott ebben. Nekem más a véleményem. Számomra ugyanis a nyereség, amelyet ez az alapos feltárás hozott, annál értékesebb volt. Max Planck: Válogatott tanulmányok Budapest, 1982 – fordította: Zemplén Jolán a) Mi a foton? b) Írja fel és értelmezze a foton lendületére és energiájára vonatkozó összefüggéseket! c) Ismertesse a cinklemezzel és UV-lámpával bemutatható fényelektromos jelenséget! d) Mutassa be a fotocella működését, készítsen ábrát! e) Ismertessen egy olyan mérést és annak eredményét, amelyben a fotocellát azonos színű, de különböző intenzitású, monokromatikus fénnyel világítjuk meg! Készítsen a mérési elrendezésről ábrát! f) Mutassa be, hogy az előbbi elrendezésben milyen mérési eredményt kapunk, ha azonos intenzitású, de különböző színű, monokromatikus fénnyel világítjuk meg a fotocellát! g) Kinek a nevéhez köthető a fenti eredmények fotonelmélettel való magyarázata? h) Adja meg a fényelektromos jelenséget leíró egyenletet! i) Hogyan határozható meg a korábban alkalmazott mérési elrendezéssel a Planck-állandó?", "utmutato": [{"src": "assets/exams/2024maj/II-3-ut.png", "w": 1058, "h": 839}]}], "kifejtes": [{"src": "assets/exams/2024maj/II-kifejtes.png", "w": 1058, "h": 1471}]}, "III": [{"nr": 1, "kepek": [{"src": "assets/exams/2024maj/III-1.png", "w": 1058, "h": 317}], "szoveg": "1. Egy L = 80 cm hosszú, homogén anyageloszlású deszka csuklóval csatlakozik a falhoz. A deszka tömege 4 kg, a ráhelyezett 1,2 kg tömegű doboz tömegközéppontja a faltól x = 25 cm távol van. A deszkát rögzítő kötél  = 40°-os szöget zár be a vízszintessel. a) Mekkora erő ébred a kötélben? b) Mekkora és milyen irányú erő terheli a csuklót? g = 9,8 m/s 2", "pont": 12, "reszek": [{"betu": "a", "pont": 5}, {"betu": "b", "pont": 7}], "megoldas": [{"src": "assets/exams/2024maj/III-1-ut.png", "w": 1058, "h": 1226}]}, {"nr": 2, "kepek": [{"src": "assets/exams/2024maj/III-2.png", "w": 1058, "h": 306}], "szoveg": "2. A távközlési műholdak az Egyenlítő felett keringenek oly módon, hogy mindig a Föld azonos pontja felett tartózkodjanak. Ezt nevezik geostacionárius pályának. a) Milyen magasan keringenek a műholdak ezen a pályán a Föld felszíne felett? b) Hányad része ebben a magasságban a műholdra ható gravitációs erő a Föld felszínén mérhetőhöz képest? A Föld tömege M = 5,97  10 24 kg, egyenlítői sugara R = 6380 km, a gravitációs állandó F N  m 2   6 , 67  10  11 . kg 2", "pont": 12, "reszek": [{"betu": "a", "pont": 8}, {"betu": "b", "pont": 4}], "megoldas": [{"src": "assets/exams/2024maj/III-2-ut.png", "w": 1058, "h": 1436}]}, {"nr": 3, "kepek": [{"src": "assets/exams/2024maj/III-3.png", "w": 1058, "h": 1442}], "szoveg": "3. Egy síklemez mögött, vele párhuzamos 0,5 T indukciójú mágneses tér van az ábrának megfelelően. A lemez kis nyílásán keresztül hidrogén- és deutériumionokat lövünk be a lemez síkjára merőlegesen, 10 7 m/s sebességgel. (A deutérium vagy nehézhidrogén a hidrogén olyan izotópja, amelynek a magja egy protonból és egy neutronból áll. A hidrogénion neve proton, a deutériumion neve deuteron.) a) A belépőnyílástól mekkora távolságra csapódnak a lemezhez a részecskék? b) Mennyi ideig mozognak a részecskék a mágneses mezőben? A deuteron tömege 3,34⸱10 -27 kg, a protoné 1,67⸱10 -27 kg, a töltése mindkettőnek 1,6⸱10 -19 C.", "pont": 12, "reszek": [{"betu": "a", "pont": 9}, {"betu": "b", "pont": 3}], "megoldas": [{"src": "assets/exams/2024maj/III-3-ut.png", "w": 1058, "h": 1441}]}, {"nr": 4, "kepek": [{"src": "assets/exams/2024maj/III-4.png", "w": 1058, "h": 1472}], "szoveg": "4. Egy m = 668 g tömegű rézdob köré nylonszalagot csévélünk az ábrán látható módon. A szalagot egy rugó és egy, a végére akasztott súly feszíti. A rézdobot egy d = 20 cm hosszú hajtókarral forgathatjuk. A hajtókart 6,4 N erővel egyenletesen forgatni kezdjük, az erő iránya a fogantyúra és a hajtókarra mindvégig merőleges. A forgatás során az állandó szögsebességgel forgó hengert a szalag folyamatosan dörzsöli. Eközben a szalag végén lévő súly helyzete változatlan. Ha a rézhengert 180-szor körbeforgatjuk, a hőmérő 5 °C hőmérséklet-emelkedést mér. Határozza meg a mérési adatok alapján a réz fajhőjét, ha tudjuk, hogy a kísérlet során fejlődő hő 90%-a melegíti a rézhengert!", "pont": 11, "reszek": [], "megoldas": [{"src": "assets/exams/2024maj/III-4-ut.png", "w": 1058, "h": 866}]}]}];
  if (typeof module !== "undefined") module.exports = PO.exams;
})(typeof globalThis !== "undefined" ? globalThis : this);
